                             <div class=\"text-right\"><a class=\"card-link\" @click=\"poup()\"><small>Reset New Password?</small></a></div>\r\n                                                  </div>\r\n                                                  <button type=\"submit\" class=\"btn btn-primary glow w-100 position-relative\">Login<i id=\"icon-arrow\" class=\"bx bx-right-arrow-alt\"></i></button>\r\n                                              </form>\r\n                                              <hr> \r\n                                          </div>\r\n                                      </div>\r\n                                  </div>\r\n                              </div>\r\n                              <!-- right section image -->\r\n                              \r\n                          </div>\r\n                      </div>\r\n                  </div>\r\n                  <modal width=\"65%\" height=\"40%\" style=\"padding:50px\" name=\"popup-singel\">\r\n                    <i @click=\"hide_pop()\" class=\"bx bx-x-circle  x-circle\"></i>\r\n                    <div class=\"app-content \"> \r\n                            <h4 v-if=\"step == 1\">Forgot Password</h4> \r\n                            <h4 v-if=\"step == 2\">Submit OTP</h4> \r\n                            <h4 v-if=\"step == 3\">Reset New Password</h4> \r\n                            <table class=\"table table-bordered table-striped table-sm\">\r\n                               <tbody   >  \r\n                                  <tr v-if=\"step == 1\"> \r\n                                      <th colspan=\"4\" class=\"text-center\"> \r\n                                          <input class=\"form-control\"  v-model=\"forget.email\" name=\"email\" placeholder=\"Username\"  > \r\n                                      </th>\r\n                                      <th class=\"text-center\">\r\n                                        <button @click=\"forgotPassword()\"  class=\"btn btn-success\">Submit</button>\r\n                                     </th> \r\n                                  </tr>\r\n                                  <tr v-if=\"step == 2\"> \r\n                                    <th colspan=\"4\" class=\"text-center\"> \r\n                                        <input class=\"form-control\"  v-model=\"forget.code\" name=\"code\" placeholder=\"OTP Code\"  > \r\n                                    </th>\r\n                                    <th class=\"text-center\">\r\n                                      <button @click=\"forgotPasswordCode()\"  class=\"btn btn-success\">Submit</button>\r\n                                   </th> \r\n                                </tr>\r\n                                <tr v-if=\"step == 3\"> \r\n                                  <th colspan=\"4\" class=\"text-center\"> \r\n                                      <input class=\"form-control\" type=\"password\" v-model=\"forget.password\" name=\"code\" placeholder=\"Password\"  > \r\n                                  </th>\r\n                                  <th colspan=\"4\" class=\"text-center\"> \r\n                                      <input class=\"form-control\" type=\"password\" v-model=\"forget.confirm_password\" name=\"code\" placeholder=\"Confirm Password\"  > \r\n                                  </th>\r\n                                  <th class=\"text-center\">\r\n                                    <button @click=\"forgotPasswordNewPass()\"  class=\"btn btn-success\">Submit</button>\r\n                                 </th> \r\n                              </tr>\r\n                               </tbody> \r\n                            </table> \r\n                       </div>\r\n                 </modal>\r\n              </section>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</template>\r\n<script>\r\nimport axios from \"./axios_instance\";\r\nimport { Form } from \"vform\";\r\nexport default {\r\n  name: \"App\",\r\n  base_url: window.base_url,\r\n  components: { \r\n  },\r\n  data() {\r\n    return { \r\n      api_url: window.api_url,\r\n      base_url: window.base_url,\r\n      step : 1 ,\r\n      token: this.$localStorage.get(\"d_token\"),\r\n      loginForm: new Form({ \r\n        email: \"\", \r\n        password: \"\", \r\n      }), \r\n      forget: new Form({ \r\n        email: \"\",\r\n        code : \"\",\r\n        password : \"\",\r\n        confirm_password : \"\" \r\n      }), \r\n    };\r\n  },\r\n  methods: {\r\n    poup(){\r\n        this.$modal.show(\"popup-singel\"); \r\n    },\r\n    hide_pop() {\r\n      this.step = 1; \r\n        this.$modal.hide(\"popup-singel\");\r\n    },\r\n    forgotPassword(){\r\n      console.log(this.forget);\r\n     \r\n        let loader = this.$loading.show();\r\n        this.forget.post(this.api_url + \"auth/mailcheck\",{\r\n                headers: {\r\n                  \"Content-Type\": \"application/json\",  \r\n                  Authorization: this.token ? `Bearer ${this.token}` : \"\"\r\n                  }, \r\n                }).then((res) => {\r\n          if(res.data.status == 1){\r\n            this.$toasted.show(res.data.message, {\r\n              theme: \"outline\",\r\n              duration: 5000,\r\n              position: \"top-right\",\r\n            }); \r\n           this.step = 2 ;\r\n          }\r\n          if(res.data.status == 0){\r\n           this.$toasted.show(res.data.message, {\r\n              theme: \"bubble\",\r\n               duration: 5000,\r\n              position: \"bottom-right\",\r\n            });\r\n          } \r\n          loader.hide(); \r\n        },(error)=>{\r\n          console.log(error);\r\n           loader.hide(); \r\n        })  \r\n    },\r\n    forgotPasswordCode(){\r\n      console.log(this.forget);\r\n     \r\n         let loader = this.$loading.show();\r\n        this.forget.post(this.api_url + \"auth/mailcheck_code\",{\r\n                headers: {\r\n                  \"Content-Type\": \"application/json\",  \r\n                  Authorization: this.token ? `Bearer ${this.token}` : \"\"\r\n                  }, \r\n                }).then((res) => {\r\n          if(res.data.status == 1){\r\n            this.step = 3 ; \r\n            this.$toasted.show(res.data.message, {\r\n              theme: \"outline\",\r\n              duration: 5000,\r\n              position: \"top-right\",\r\n            }); \r\n           \r\n          }\r\n          if(res.data.status == 0){\r\n           this.$toasted.show(res.data.message, {\r\n              theme: \"bubble\",\r\n               duration: 5000,\r\n              position: \"bottom-right\",\r\n            });\r\n          } \r\n          loader.hide(); \r\n        },(error)=>{\r\n          console.log(error);\r\n           loader.hide(); \r\n        })  \r\n    },\r\n    forgotPasswordNewPass(){\r\n      console.log(this.forget);\r\n     \r\n         let loader = this.$loading.show();\r\n        this.forget.post(this.api_url + \"auth/reset_password\",{\r\n                headers: {\r\n                  \"Content-Type\": \"application/json\",  \r\n                  Authorization: this.token ? `Bearer ${this.token}` : \"\"\r\n                  }, \r\n                }).then((res) => {\r\n          if(res.data.status == 1){\r\n            this.hide_pop();\r\n            //this.step = 3 ; \r\n            this.$toasted.show(res.data.message, {\r\n              theme: \"outline\",\r\n              duration: 5000,\r\n              position: \"top-right\",\r\n            }); \r\n           \r\n          }\r\n          if(res.data.status == 0){\r\n           this.$toasted.show(res.data.message, {\r\n              theme: \"bubble\",\r\n               duration: 5000,\r\n              position: \"bottom-right\",\r\n            });\r\n          } \r\n          loader.hide(); \r\n        },(error)=>{\r\n          console.log(error);\r\n           loader.hide(); \r\n        })  \r\n    },\r\n    login(){\r\n      try {\r\n        let loader = this.$loading.show();\r\n        this.loginForm.post(this.api_url + \"auth/login\",{\r\n                headers: {\r\n                  \"Content-Type\": \"application/json\",  \r\n                  Authorization: this.token ? `Bearer ${this.token}` : \"\"\r\n                  }, \r\n                }).then((res) => {\r\n          if(res.data.status == 1){\r\n            this.$toasted.show(res.data.message, {\r\n              theme: \"outline\",\r\n              duration: 5000,\r\n              position: \"top-right\",\r\n            }); \r\n            this.$localStorage.set(\"d_token\", res.data.access_token);\r\n            this.$localStorage.set(\"user\", JSON.stringify(res.data.user)); \r\n            this.getTargetAchievement();\r\n           // console.log(res.data.user);\r\n            this.$router.push(\"/home/login\"); \r\n            //this.$router.go(\"/home/l\");\r\n          }\r\n          if(res.data.status == 2){\r\n            this.$toasted.show(res.data.message, {\r\n              theme: \"outline\",\r\n              duration: 5000,\r\n              position: \"top-right\",\r\n            }); \r\n            this.$localStorage.set(\"d_token\", res.data.access_token);\r\n            this.$localStorage.set(\"user\", JSON.stringify(res.data.user)); \r\n            this.getTargetAchievement();\r\n            // console.log(res.data.user);\r\n            this.$router.push(\"/adupdate\"); \r\n            //this.$router.go(\"/home/l\");\r\n          }\r\n          if(res.data.status == 0){\r\n           this.$toasted.show(res.data.message, {\r\n              theme: \"bubble\",\r\n               duration: 5000,\r\n              position: \"bottom-right\",\r\n            });\r\n\r\n            console.log('test data',res.data);\r\n          } \r\n          loader.hide(); \r\n        },(error)=>{\r\n          console.log(error);\r\n           loader.hide(); \r\n        })\r\n      } catch (error) {\r\n         // loader.hide(); \r\n        console.log(error);\r\n      }\r\n    },\r\n    async getTargetAchievement(){  \r\n                let  where = '?' ;\r\n                let token =  this.$localStorage.get(\"d_token\")\r\n                \r\n                    await axios\r\n                        .get(this.api_url + \"dashboard\" + where, {\r\n                            headers: {\r\n                                \"Content-Type\": \"application/json\",\r\n                                Authorization: token ? `Bearer ${token}` : \"\"\r\n                            },\r\n                        })\r\n                        .then(({\r\n                            data\r\n                        }) => {\r\n                            if (data.success) {  \r\n                                    let achievement = data.data.achievement ;\r\n                                    let target = data.data.target ; \r\n                                    this.$localStorage.set(\"achievement\", JSON.stringify(achievement) );\r\n                                    this.$localStorage.set(\"target\", JSON.stringify(target) );\r\n                                 \r\n                            }\r\n                            \r\n                        });\r\n                \r\n           // }, 3000);\r\n        },\r\n    async demoDownload() {\r\n        window.location.href = window.location.origin + \"/demo/Privacy_Policy.pdf\"\r\n    }      \r\n  },\r\n  created() {},\r\n};\r\n</script>\r\n\r\n<style>\r\ninput.form-control.input_custom_2.is-invalid {\r\n  border-color: #f00;\r\n}\r\n</style>\r\n","import mod from \"-!../node_modules/cache-loader/dist/cjs.js??ref--12-0!../node_modules/thread-loader/dist/cjs.js!../node_modules/babel-loader/lib/index.js!../node_modules/cache-loader/dist/cjs.js??ref--0-0!../node_modules/vue-loader/lib/index.js??vue-loader-options!./login.vue?vue&type=script&lang=js&\"; export default mod; export * from \"-!../node_modules/cache-loader/d