atus: status,\r\n            name : item.name\r\n        })\r\n        try {\r\n         let loader = this.$loading.show();\r\n            editForm.put(this.api_url + \"departments/\"+ item.id, {\r\n                headers: {\r\n                \"Content-Type\": \"application/json\", \r\n                Authorization: this.token ? `Bearer ${this.token}` : \"\"\r\n                },\r\n            }).then((res) => {\r\n                console.log(res);\r\n                if(res.data.success){ \r\n                    this.$toasted.show(res.data.message, {\r\n                        theme: \"bubble\",\r\n                        duration: 5000,\r\n                        position: \"bottom-right\",\r\n                        });\r\n                } \r\n                loader.hide(); \r\n                this.getItems();\r\n            },(error)=>{\r\n            console.log(error);\r\n            loader.hide(); \r\n            })\r\n        } catch (error) {\r\n            // loader.hide(); \r\n            console.log(error);\r\n        }\r\n    }, \r\n    async delete_row(id){ \r\n        let loader = this.$loading.show();\r\n        try {\r\n            await axios\r\n            .delete(this.api_url + \"departments/\"+id, {\r\n                    headers: {\r\n                    \"Content-Type\": \"application/json\", \r\n                    Authorization: this.token ? `Bearer ${this.token}` : \"\"\r\n                    },\r\n                })\r\n            .then(({ res }) => {  \r\n                    this.$toasted.show(res.data.message, {\r\n                        theme: \"bubble\",\r\n                        duration: 5000,\r\n                        position: \"bottom-right\",\r\n                        });\r\n                    this.getItems();\r\n               \r\n                loader.hide();\r\n            });\r\n        } catch (error) {\r\n            loader.hide();\r\n        }\r\n      },\r\n       async getItems(){\r\n           //departments_all\r\n           let loader = this.$loading.show();\r\n           await axios.get(this.api_url + \"dept_permission?user_id=\"+this.user_id, {\r\n                    headers: {\r\n                    \"Content-Type\": \"application/json\", \r\n                    Authorization: this.token ? `Bearer ${this.token}` : \"\"\r\n                    },\r\n                })\r\n            .then(({ data }) => {  \r\n                this.items =  data.data\r\n                loader.hide();\r\n                console.log(this.WingsItems );   \r\n            }); \r\n           \r\n      },\r\n      create(){ \r\n                try {\r\n                    let loader = this.$loading.show(); \r\n                    this.dept_permission.dept_selects = this.items ;\r\n                    this.dept_permission.user_id = this.user_id ;\r\n                    this.dept_permission.post(this.api_url + \"dept_permission\", {\r\n                        headers: {\r\n                        \"Content-Type\": \"application/json\", \r\n                        Authorization: this.token ? `Bearer ${this.token}` : \"\"\r\n                        },\r\n                    }).then((res) => { \r\n                        if(res.data.success){\r\n                            this.$toasted.show(res.data.message, {\r\n                                theme: \"bubble\",\r\n                                duration: 5000,\r\n                                position: \"bottom-right\",\r\n                            });\r\n                        } \r\n                        loader.hide();  \r\n                        this.hide_pop();\r\n                       // this.$router.push('/daily_work');\r\n                    },(error)=>{\r\n                    console.log(error);\r\n                    loader.hide(); \r\n                    })\r\n                } catch (error) {\r\n                    // loader.hide(); \r\n                    console.log(error);\r\n                }\r\n                },\r\n      