\"form-group\">\r\n                  <select  v-on:change=\"getItems()\"  name=\"role_id\" v-model=\"filterForm.role_id\"   class=\"form-control\">\r\n                      <option value=\"\">Select one</option>\r\n                      <option  v-for=\"row in roles\" :key=\"row.id\" :value=\"row.id\">{{ row.title}}</option>  \r\n                  </select>\r\n                </fieldset>\r\n              </div>\r\n\r\n              <div class=\"col-sm-4 col-lg-2\" v-if=\"(deptItems.length > 1)\" >\r\n                <label for=\"users-list-verified\">Department</label>\r\n                <fieldset class=\"form-group\">\r\n                  <select class=\"form-control\" v-on:change=\"getWing()\" v-model=\"filterForm.dept_id\"\r\n                    id=\"users-list-verified\">\r\n                    <option value=\"\">Select One</option>\r\n                    <option v-for=\"row in deptItems\" :key=\"row.id\" :value=\"row.id\">\r\n                      {{ row.name }}\r\n                    </option>\r\n                  </select>\r\n                </fieldset>\r\n              </div>\r\n              <div class=\"ccol-sm-4 col-lg-2\" v-if=\"role_id < 6\">\r\n                <label for=\"users-list-verified\">Wings</label>\r\n                <fieldset class=\"form-group\">\r\n                  <select class=\"form-control\" v-on:change=\"getItems()\" v-model=\"filterForm.wing_id\"\r\n                    id=\"users-list-verified\">\r\n                    <option value=\"\">Select One</option>\r\n                    <option v-for=\"row in WingsItems\" :key=\"row.id\" :value=\"row.id\">\r\n                      {{ row.wing_title }}\r\n                    </option>\r\n                  </select>\r\n                </fieldset>\r\n              </div>\r\n            </div>\r\n          </div>          \r\n          <!-- Zero configuration table -->\r\n          <section id=\"basic-datatable\">\r\n            <div class=\"row\">\r\n              <div class=\"col-12\">\r\n                <div class=\"card\">\r\n                  <div class=\"card-content\">\r\n                    <div class=\"card-body card-dashboard\">\r\n\r\n                      <div class=\"table-responsive\">\r\n                        <table class=\"table table-striped\">\r\n                          <thead>\r\n                          <tr>\r\n                            <th>Name</th>\r\n                            <th>User Name <input type=\"text\" class=\"text-center\" placeholder=\"Search\"\r\n                                                      v-model=\"search\"></th>\r\n                            <th>Department</th>\r\n                            <th>Organization Email</th>\r\n                            <th>Employee ID</th>\r\n                            <th>Channel</th>\r\n                            <th>User Role</th>\r\n                            <th>Action</th>\r\n\r\n                          </tr>\r\n                          </thead>\r\n                          <tbody>\r\n                          <tr v-for=\"row in items\" :key=\"row.id\">\r\n                            <td>{{ row.name }}</td>\r\n                            <td>{{ row.email }}</td>\r\n                            <td>{{ row.deptjoin ? row.deptjoin.name : '' }}</td>\r\n                            <td>{{ row.ad_mail }}</td>\r\n                            <td>{{ row.employee_id }}</td>\r\n                            <td>{{ row.employee_id }}</td>\r\n                            <td>{{ row.rolejoin ? row.rolejoin.title : '' }}</td>\r\n                            <td>\r\n                              <div class=\"dropup\">\r\n                                <span\r\n                                    class=\"bx bx-dots-vertical-rounded font-medium-3 dropdown-toggle nav-hide-arrow cursor-pointer\"\r\n                                    data-toggle=\"dropdown\" aria-haspopup=\"true\"\r\n                                    aria-expanded=\"false\" role=\"menu\">\r\n                                </span>\r\n                                <div class=\"dropdown-menu dropdown-menu-right\">\r\n                                  <router-link class=\"dropdown-item\" :to=\"{ path: '/edit_user/'+row.id }\"><i\r\n                                      class=\"bx bx-edit-alt mr-1\"></i> Edit\r\n                                  </router-link>\r\n                                  <router-link\r\n                                      v-if=\"row.role_id == 5 || row.role_id == 1 || row.role_id == 2 || row.role_id == 3 || row.role_id == 4  || row.role_id == 8\"\r\n                                      class=\"dropdown-item\" :to=\"{ path: '/dept_permission/'+row.id }\"><i\r\n                                      class=\"bx bx-edit-alt mr-1\"></i> Dept. Permission\r\n                                  </router-link>\r\n                                  <router-link\r\n                                      class=\"dropdown-item\" :to=\"{ path: '/dept_transfer/'+row.id }\"><i\r\n                                      class=\"bx bx-edit-alt mr-1\"></i> Department Transfer\r\n                                  </router-link>\r\n\r\n                                  <a class=\"dropdown-item\" @click=\"delete_row(row.id)\"><i class=\"bx bx-trash mr-1\"></i>\r\n                                    Delete</a>\r\n                                </div>\r\n                              </div>\r\n                            </td>\r\n                          </tr>\r\n                          <tr v-if=\"items.length < 1\">\r\n                            <td colspan=\"4\">Data not found</td>\r\n                          </tr>\r\n\r\n                          </tbody>\r\n                        </table>\r\n                      </div>\r\n\r\n                    </div>\r\n                  </div>\r\n                </div>\r\n              </div>\r\n            </div>\r\n          </section>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n</template>\r\n\r\n<script>\r\nimport axios from \"../../axios_instance\";\r\nimport { Form } from \"vform\"; \r\nexport default {\r\n  props: {},\r\n  components: {\r\n    // VueRecaptcha, facebookLogin\r\n  },\r\n  data() {\r\n    return {\r\n      deptItems: [],\r\n      search: '',\r\n      base_url: window.base_url,\r\n      api_url: window.api_url,\r\n      role_id: '',\r\n      user_data: JSON.parse(this.$localStorage.get(\"user\")),\r\n      employeeItem: [],\r\n      token: this.$localStorage.get(\"d_token\"),\r\n      items: [],\r\n      status: '',\r\n      mployeeItem: [],\r\n      WingsItems : [],\r\n      wing_user : '',\r\n      roles: [] ,  \r\n      filterForm: new Form({\r\n        dept_id: this.$route.query.dept_id ? this.$route.query.dept_id : \"\",\r\n        wing_id: \"\",\r\n        user_id: \"\",\r\n        role_id: \"\",\r\n      }),\r\n\r\n    };\r\n  },\r\n  created() {\r\n    this.role_id = this.user_data.role_id;\r\n    this.getItems();\r\n    this.getDept();\r\n    this.getRole();\r\n    if(this.role_id == 5){\r\n      this.getWing();\r\n    }\r\n  },\r\n  methods: {\r\n    //PAGINATION\r\n    setPage: function (pageNumber) {\r\n      this.currentPage = pageNumber\r\n    },   \r\n    async getEmployee() {\r\n      //if (this.filterForm.wing_id) {\r\n      let where = '?1=1';\r\n      if (this.filterForm.wing_id) {\r\n        where += '&wing_id=' + this.filterForm.wing_id;\r\n      }\r\n      if (this.filterForm.dept_id) {\r\n        where += '&dept_id=' + this.filterForm.dept_id;\r\n      }     \r\n      await axios.get(this.api_url + \"users\" + where, {\r\n        headers: {\r\n          \"Content-Type\": \"application/json\",\r\n          Authorization: this.token ? `Bearer ${this.token}` : \"\"\r\n        },\r\n      })\r\n      .then(({ data }) => {\r\n        this.employeeItem = data.data;\r\n        // this.getItems();\r\n      });\r\n      //}\r\n\r\n    },\r\n    async getWing() {\r\n      await axios.get(this.api_url + \"wings?dept_id=\" + this.filterForm.dept_id, {\r\n        headers: {\r\n          \"Content-Type\": \"application/json\",\r\n          Authorization: this.token ? `Bearer ${this.token}` : \"\"\r\n        },\r\n      })\r\n      .then(({ data }) => {\r\n        this.getItems();\r\n        this.WingsItems = data.data;\r\n        console.log(this.WingsItems);\r\n      });\r\n    },\r\n    async getDept() {\r\n      let loader = this.$loading.show();\r\n      this.getDepartments(this.status).then(({ data }) => {\r\n        if (data.success) {\r\n          loader.hide();\r\n          this.deptItems = data.data;\r\n        } else {\r\n          loader.hide();\r\n        }\r\n      });\r\n    },\r\n    async delete_row(id) {\r\n      console.log(id);\r\n      let loader = this.$loading.show();\r\n      try {\r\n        await axios\r\n            .delete(this.api_url + \"users/\" + id, {\r\n              headers: {\r\n                \"Content-Type\": \"application/json\",\r\n                Authorization: this.token ? `Bearer ${this.token}` : \"\"\r\n              },\r\n            })\r\n            .then(({\r\n                     res\r\n                   }) => {\r\n              if (res.data.success) {\r\n                this.$toasted.show(res.data.message, {\r\n                  theme: \"bubble\",\r\n                  duration: 5000,\r\n                  position: \"bottom-right\",\r\n                });\r\n              }\r\n              loader.hide();\r\n            });\r\n      } catch (error) {\r\n        loader.hide();\r\n      }\r\n    },\r\n    async getItems() {\r\n      let where = '?';\r\n      if(this.filterForm.role_id){\r\n          where += '&role_id=' + this.filterForm.role_id;\r\n      }\r\n      if (this.dept_id) {\r\n          where += '&dept_id=' + this.dept_id;\r\n      }\r\n       if (this.filterForm.dept_id) {\r\n          where += '&dept_id=' + this.filterForm.dept_id;\r\n      }\r\n      if(this.filterForm.wing_id){\r\n        where += '&wing_id=' + this.filterForm.wing_id;\r\n      }\r\n      if(this.filterForm.user_id){\r\n        where += '&wing_id=' + this.filterForm.user_id;\r\n      }       \r\n      let loader = this.$loading.show();\r\n      try {\r\n        await axios\r\n            .get(this.api_url + \"users\" + where, {\r\n              headers: {\r\n                \"Content-Type\": \"application/json\",\r\n                Authorization: this.token ? `Bearer ${this.token}` : \"\"\r\n              },\r\n            })\r\n            .then(({\r\n                     data\r\n                   }) => {\r\n              //if (data.success) {\r\n                this.items = data.data\r\n               console.log('user list',this.items);\r\n              //}s\r\n              loader.hide();\r\n            });\r\n      } catch (error) {\r\n        loader.hide();\r\n      }\r\n    },\r\n    async getRole(){ \r\n        await axios.get(this.api_url + \"role\", {\r\n                headers: {\r\n                \"Content-Type\": \"application/json\", \r\n                Authorization: this.token ? `Bearer ${this.token}` : \"\"\r\n                },\r\n            })\r\n        .then(({ data }) => {  \r\n            this.roles =  data.data ;\r\n            console.log(this.roles );   \r\n        });\r\n    },\r\n\r\n  },\r\n  computed: {\r\n    filteredItems() {\r\n      return this.items.filter(item => {\r\n        return item.email.toLowerCase().indexOf(this.search.toLowerCase()) > -1\r\n      })\r\n    },\r\n  },\r\n}\r\n;\r\n</script>\r\n","import mod from \"-!../../../node_modules/cache-loader/dist/cjs.js??ref--12-0!../../../node_modules/thread-loader/dist/cjs.js!../../../node_modules/babel-loader/lib/index.js!../../../node_modules/cache-loader/dist/cjs.js??ref--0-0!../../../node_modules/vue-loader/lib/index.js??vue-loader-options!./index.vue?vue&type=script&lang=js&\"; export default mod; export * from \"-!../../../node_modules/cache-loader/dist/cjs.js??ref--12-0!../../../node_modules/thread-loader/dist/cjs.js!../../../node_modules