mat_Date(this.filterForm.date);\r\n      }\r\n\r\n      let loader = this.$loading.show();\r\n      try {\r\n        await axios\r\n            .get(this.api_url + \"daliy_not_update/\" + where, {\r\n              headers: {\r\n                \"Content-Type\": \"application/json\",\r\n                Authorization: this.token ? `Bearer ${this.token}` : \"\"\r\n              },\r\n            })\r\n            .then(({\r\n                     data\r\n                   }) => {\r\n              if (data.success) {\r\n                this.items = data.data;\r\n\r\n              }\r\n              loader.hide();\r\n            });\r\n      } catch (error) {\r\n        loader.hide();\r\n      }\r\n    },\r\n\r\n    //REPORT GENERATED BY DATE SELECT\r\n    dateSelected(){\r\n      this.getItems()\r\n    },\r\n  },\r\n  computed: {\r\n    filteredItems() {\r\n      return this.items.filter(item => {\r\n        return item.deptjoin.name.toLowerCase().indexOf(this.search.toLowerCase()) > -1\r\n      })\r\n    }\r\n  },\r\n};\r\n</script>\r\n    ","import mod from \"-!../../../node_modules/cache-loader/dist/cjs.js??ref--12-0!../../../node_modules/thread-loader/dist/cjs.js!../../../node_modules/babel-loader/lib/index.js!../../../node_modules/cache-loader/dist/cjs.js??ref--0-0!../../../node_modules/vue-loader/lib/index.js??vue-loader-options!./daliy_not_update.vue?vue&type=script&lang=js&\"; export default mod; export * from \"-!../../../node_modules/cache-loader/dist/cjs.js??ref--12-0!../../../node_modules/thread-loader/dist/cjs.js!../../../node_modules/babel-loader/lib/index.js!../../../node_modules/cache-loader/dist/cjs.js??ref--0-0!../../../node_modules/vue-loader/lib/index.js??vue-loader-options!./daliy_not_update.vue?vue&type=script&lang=js&\"","import { render, staticRenderFns } from \"./daliy_not_update.vue?vue&type=template&id=21cbf75d&\"\nimport script from \"./daliy_not_update.vue?vue&type=script&lang=js&\"\nexport * from \"./daliy_not_update.vue?vue&type=script&lan