.id ==\r\n                                            'work_with_plan' ||\r\n                                          tabs[type_select].id ==\r\n                                            'without_plan' ||\r\n                                          tabs[type_select].id == 'undone'\r\n                                        \"\r\n                                      >\r\n                                        Details\r\n                                        <!-- <a class=\"btn btn-primary add-btn\" @click=\"delete_row(item.id)\" > <i class=\"bx bx-add-alt\"></i>Delete  </a>  -->\r\n                                        <a\r\n                                          class=\"btn btn-primary add-btn\"\r\n                                          @click=\"show_pop(item)\"\r\n                                        >\r\n                                          <i class=\"bx bx-add-alt\"></i>Comment\r\n                                        </a>\r\n                                      </th>\r\n                                    </tr>\r\n                                    <tr\r\n                                      v-if=\"\r\n                                        tabs[type_select].id ==\r\n                                          'work_with_plan' ||\r\n                                        tabs[type_select].id ==\r\n                                          'without_plan' ||\r\n                                        tabs[type_select].id == 'undone'\r\n                                      \"\r\n                                    >\r\n                                      <td colspan=\"2\" class=\"text-left\">\r\n                                        <p v-html=\"item.monthly_work\"></p>\r\n                                      </td>\r\n                                    </tr>\r\n\r\n                                    <tr>\r\n                                      <th\r\n                                        colspan=\"2\"\r\n                                        class=\"text-center\"\r\n                                        v-if=\"tabs[type_select].id == 'others'\"\r\n                                      >\r\n                                        Top Priority for\r\n                                        {{ monthNames[item.month] }} month\r\n                                        <!-- <a class=\"btn btn-primary add-btn\" @click=\"delete_row(item.id)\" > <i class=\"bx bx-add-alt\"></i>Delete  </a>  -->\r\n                                        <a\r\n                                          class=\"btn btn-primary add-btn\"\r\n                                          @click=\"show_pop()\"\r\n                                        >\r\n                                          <i class=\"bx bx-add-alt\"></i>Comment\r\n                                        </a>\r\n                                      </th>\r\n                                    </tr>\r\n                                    <tr v-if=\"tabs[type_select].id == 'others'\">\r\n                                      <td colspan=\"2\" class=\"text-left\">\r\n                                        <p v-html=\"item.topforcurrentmonth\"></p>\r\n                                      </td>\r\n                                    </tr>\r\n\r\n                                    <tr>\r\n                                      <th\r\n                                        colspan=\"2\"\r\n                                        class=\"text-center\"\r\n                                        v-if=\"tabs[type_select].id == 'others'\"\r\n                                      >\r\n                                        Man Power Efficiency:\r\n                                      </th>\r\n                                    </tr>\r\n                                    <tr v-if=\"tabs[type_select].id == 'others'\">\r\n                                      <td colspan=\"2\" class=\"text-left\">\r\n                                        <p\r\n                                          v-html=\"item.man_power_efficiency\"\r\n                                        ></p>\r\n                                      </td>\r\n                                    </tr>\r\n                                    <tr>\r\n                                      <td colspan=\"2\" class=\"text-left\">\r\n                                        <ul\r\n                                          class=\"list-group\"\r\n                                          v-if=\"item.files.length > 0\"\r\n                                        >\r\n                                          <li class=\"list-group-item disabled\">\r\n                                            Files\r\n                                          </li>\r\n                                          <li\r\n                                            v-for=\"file in item.files\"\r\n                                            :key=\"file.id\"\r\n                                            class=\"list-group-item\"\r\n                                          >\r\n                                            <img\r\n                                              v-if=\"file.file_type == 'pdf'\"\r\n                                              width=\"30px\"\r\n                                              :src=\"\r\n                                                base_url +\r\n                                                'assets/app-assets/images/pages/pdf.png'\r\n                                              \"\r\n                                            />\r\n                                            <img\r\n                                              v-if=\"file.file_type == 'docx'\"\r\n                                              width=\"30px\"\r\n                                              :src=\"\r\n                                                base_url +\r\n                                                'assets/app-assets/images/pages/docs.png'\r\n                                              \"\r\n                                            />\r\n                                            <img\r\n                                              v-if=\"file.file_type == 'png'\"\r\n                                              width=\"30px\"\r\n                                              :src=\"\r\n                                                base_url +\r\n                                                'assets/app-assets/images/pages/png.png'\r\n                                              \"\r\n                                            />\r\n                                            <img\r\n                                              v-if=\"file.file_type == 'jpeg'\"\r\n                                              width=\"30px\"\r\n                                              :src=\"\r\n                                                base_url +\r\n                                                'assets/app-assets/images/pages/jpeg.png'\r\n                                              \"\r\n                                            />\r\n                                            <img\r\n                                              v-if=\"file.file_type == 'jpg'\"\r\n                                              width=\"30px\"\r\n                                              :src=\"\r\n                                                base_url +\r\n                                                'assets/app-assets/images/pages/jpg.png'\r\n                                              \"\r\n                                            />\r\n                                            <img\r\n                                              v-if=\"file.file_type == 'xlsx'\"\r\n                                              width=\"30px\"\r\n                                              :src=\"\r\n                                                base_url +\r\n                                                'assets/app-assets/images/pages/Google sheets.png'\r\n                                              \"\r\n                                            />\r\n                                            <i @click=\"fileDownload(file.id)\">\r\n                                              {{ file.file_caption }}</i\r\n                                            >\r\n                                            <a class=\"\"></a>\r\n                                          </li>\r\n                                        </ul>\r\n                                      </td>\r\n                                    </tr>\r\n                                  </template>\r\n                                </tbody>\r\n                              </table>\r\n                              <ul\r\n                                class=\"list-group\"\r\n                                v-if=\"file_List.length > 0\"\r\n                              >\r\n                                <li class=\"list-group-item disabled\">Files</li>\r\n                                <li\r\n                                  v-for=\"(item, index) in file_List\"\r\n                                  :key=\"index\"\r\n                                  class=\"list-group-item\"\r\n                                ></li>\r\n                              </ul>\r\n                            </div>\r\n                          </div>\r\n                        </div>\r\n                      </div>\r\n                    </div>\r\n                  </div>\r\n                </div>\r\n              </div>\r\n            </div>\r\n          </section>\r\n          <modal\r\n            width=\"75%\"\r\n            height=\"80%\"\r\n            style=\"padding: 50px\"\r\n            name=\"popup-permission\"\r\n          >\r\n            <i\r\n              @click=\"hide_pop_permission()\"\r\n              class=\"bx bx-x-circle x-circle\"\r\n            ></i>\r\n            <div class=\"app-content\">\r\n              <div class=\"card\">\r\n                <table class=\"table table-bordered table-striped table-sm\">\r\n                  <tbody>\r\n                    <tr>\r\n                      <th colspan=\"2\" class=\"text-center\">\r\n                        <div class=\"form-group\">\r\n                          <label for=\"Profession\">TO Date</label>\r\n                          <div class=\"controls\">\r\n                            <datepicker\r\n                              v-model=\"daliy_mailForm.toDate\"\r\n                              name=\"to_date\"\r\n                              class=\"form-control\"\r\n                            ></datepicker>\r\n                          </div>\r\n                        </div>\r\n                      </th>\r\n                      <th colspan=\"2\" class=\"text-center\">\r\n                        <div class=\"form-group\">\r\n                          <label for=\"Profession\">From Date</label>\r\n                          <div class=\"controls\">\r\n                            <datepicker\r\n                              v-model=\"daliy_mailForm.fromDate\"\r\n                              name=\"from_date\"\r\n                              class=\"form-control\"\r\n                            ></datepicker>\r\n                          </div>\r\n                        </div>\r\n                      </th>\r\n                    </tr>\r\n                    <!-- <tr>\r\n                      <th colspan=\"4\" class=\"text-center\">\r\n                        <vue-editor\r\n                          v-model=\"daliy_mailForm.comment\"\r\n                          name=\"comment\"\r\n                          placeholder=\"Comment....\"\r\n                        ></vue-editor>\r\n                      </th>\r\n                    </tr> -->\r\n                    <tr>\r\n                      <th class=\"text-center\">\r\n                        <div class=\"form-group\">\r\n                          <label for=\"Profession\">Mail CC1</label>\r\n                          <div class=\"controls\">\r\n                            <input\r\n                              v-model=\"daliy_mailForm.mailcc1\"\r\n                              placeholder=\"example1@gmail.com\"\r\n                              class=\"form-control\"\r\n                              type=\"text\"\r\n                            />\r\n                          </div>\r\n                        </div>\r\n                      </th>\r\n                      <th class=\"text-center\">\r\n                        <div class=\"form-group\">\r\n                          <label for=\"Profession\">Mail CC3</label>\r\n                          <div class=\"controls\">\r\n                            <input\r\n                              v-model=\"daliy_mailForm.mailcc2\"\r\n                              placeholder=\"example2@gmail.com\"\r\n                              class=\"form-control\"\r\n                              type=\"text\"\r\n                            />\r\n                          </div>\r\n                        </div>\r\n                      </th>\r\n                      <th class=\"text-center\">\r\n                        <div class=\"form-group\">\r\n                          <label for=\"Profession\">Mail CC3</label>\r\n                          <div class=\"controls\">\r\n                            <input\r\n                              v-model=\"daliy_mailForm.mailcc3\"\r\n                              placeholder=\"example3@gmail.com\"\r\n                              class=\"form-control\"\r\n                              type=\"text\"\r\n                            />\r\n                          </div>\r\n                        </div>\r\n                      </th>\r\n                      <th class=\"text-center\">\r\n                        <button @click=\"monthly_permission()\" class=\"btn btn-success\">\r\n                          Send\r\n                        </button>\r\n                      </th>\r\n                    </tr>\r\n                  </tbody>\r\n                </table>\r\n              </div>\r\n            </div>\r\n          </modal>\r\n\r\n          <modal\r\n            width=\"75%\"\r\n            height=\"80%\"\r\n            style=\"padding: 50px\"\r\n            name=\"popup-singel\"\r\n          >\r\n            <i @click=\"hide_pop()\" class=\"bx bx-x-circle x-circle\"></i>\r\n            <div class=\"app-content\">\r\n              <div class=\"card\">\r\n                <table class=\"table table-bordered table-striped table-sm\">\r\n                  <tbody>\r\n                    <tr>\r\n                      <th colspan=\"4\" class=\"text-center\">\r\n                        <vue-editor\r\n                          v-model=\"daliy_mailForm.comment\"\r\n                          name=\"comment\"\r\n                          placeholder=\"Comment....\"\r\n                        ></vue-editor>\r\n                      </th>\r\n                    </tr>\r\n                    <tr>\r\n                      <th class=\"text-center\">\r\n                        <div class=\"form-group\">\r\n                          <label for=\"Profession\">Mail CC1</label>\r\n                          <div class=\"controls\">\r\n                            <input\r\n                              v-model=\"daliy_mailForm.mailcc1\"\r\n                              placeholder=\"example1@gmail.com\"\r\n                              class=\"form-control\"\r\n                              type=\"text\"\r\n                            />\r\n                          </div>\r\n                        </div>\r\n                      </th>\r\n                      <th class=\"text-center\">\r\n                        <div class=\"form-group\">\r\n                          <label for=\"Profession\">Mail CC3</label>\r\n                          <div class=\"controls\">\r\n                            <input\r\n                              v-model=\"daliy_mailForm.mailcc2\"\r\n                              placeholder=\"example2@gmail.com\"\r\n                              class=\"form-control\"\r\n                              type=\"text\"\r\n                            />\r\n                          </div>\r\n                        </div>\r\n                      </th>\r\n                      <th class=\"text-center\">\r\n                        <div class=\"form-group\">\r\n                          <label for=\"Profession\">Mail CC3</label>\r\n                          <div class=\"controls\">\r\n                            <input\r\n                              v-model=\"daliy_mailForm.mailcc3\"\r\n                              placeholder=\"example3@gmail.com\"\r\n                              class=\"form-control\"\r\n                              type=\"text\"\r\n                            />\r\n                          </div>\r\n                        </div>\r\n                      </th>\r\n                      <th class=\"text-center\">\r\n                        <button @click=\"comment()\" class=\"btn btn-success\">\r\n                          Send\r\n                        </button>\r\n                      </th>\r\n                    </tr>\r\n                  </tbody>\r\n                </table>\r\n              </div>\r\n            </div>\r\n          </modal>\r\n\r\n          <modal\r\n            width=\"75%\"\r\n            height=\"80%\"\r\n            style=\"padding: 50px; margin-left: 100px\"\r\n            name=\"singel\"\r\n          >\r\n            <i @click=\"hide_pop_singel()\" class=\"bx bx-x-circle x-circle\"></i>\r\n            <div class=\"app-content\">\r\n              <div class=\"card\">\r\n                <!-- SHOW ALL DATA -->\r\n                <div v-for=\"(item, index) in items\" :key=\"index\">\r\n                  <!--                           <div v-if=\"item.worktype == 'single_page'\"> -->\r\n                  <p v-html=\"item.monthly_work\"></p>\r\n                  <!--                           </div>-->\r\n                </div>\r\n              </div>\r\n            </div>\r\n          </modal>\r\n          <modal width=\"75%\" height=\"80%\" style=\"padding: 50px\" name=\"singel2\">\r\n            <i @click=\"hide_pop_singel2()\" class=\"bx bx-x-circle x-circle\"></i>\r\n            <div class=\"app-content\">\r\n              <div class=\"card\">\r\n                <div v-for=\"(item, index) in items\" :key=\"index\">\r\n                  <div v-if=\"item.worktype == 'single_page'\">\r\n                    <p v-html=\"item.monthly_work\"></p>\r\n                  </div>\r\n                </div>\r\n              </div>\r\n            </div>\r\n          </modal>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n</template>\r\n\r\n<script>\r\nimport axios from \"../../axios_instance\";\r\nimport { Form } from \"vform\";\r\nimport { VueEditor } from \"vue2-editor\";\r\nimport Datepicker from \"vuejs-datepicker\";\r\nexport default {\r\n  props: {},\r\n  components: {\r\n    VueEditor,\r\n    Datepicker,\r\n    // VueRecaptcha, facebookLogin\r\n  },\r\n  data() {\r\n    return {\r\n      monthNames: [\r\n        \"January\",\r\n        \"February\",\r\n        \"March\",\r\n        \"April\",\r\n        \"May\",\r\n        \"June\",\r\n        \"July\",\r\n        \"August\",\r\n        \"September\",\r\n        \"October\",\r\n        \"November\",\r\n        \"December\",\r\n      ],\r\n\r\n      base_url: window.base_url,\r\n      api_url: window.api_url,\r\n      DepartmentsItems: [],\r\n      user_data: JSON.parse(this.$localStorage.get(\"user\")),\r\n      token: this.$localStorage.get(\"d_token\"),\r\n      tabs: [],\r\n      report_type: \"\",\r\n      type_select: 0,\r\n      kraItem: [],\r\n      file_List: [],\r\n      deptSingel: [],\r\n      status: \"\",\r\n      kpiItem: [],\r\n      mosItem: [],\r\n      deptItems: [],\r\n      monthly_button: false,\r\n      items: [],\r\n      //year: this.$localStorage.get('year') ? this.$localStorage.get('year') : new Date().getFullYear(),\r\n      filterForm: new Form({\r\n        dept_id: \"\",\r\n        year: this.$localStorage.get(\"year\")\r\n          ? this.$localStorage.get(\"year\")\r\n          : new Date().getFullYear(),\r\n        month: \"\",\r\n        user_id: \"\",\r\n      }),\r\n      mail_comment: [],\r\n      daliy_mailForm: new Form({\r\n        toDate: \"\",\r\n        fromDate: \"\",\r\n        mailcc1: \"\",\r\n        mailcc2: \"\",\r\n        mailcc3: \"\",\r\n        dept_id: \"\",\r\n        report_id: \"\",\r\n        comment: \"\",\r\n        item: [],\r\n      }),\r\n    };\r\n  },\r\n  created() {\r\n    const d = new Date();\r\n    this.current_month = d.getMonth();\r\n    this.role_id = this.user_data.role_id;\r\n    if(this.role_id == 5 ){\r\n        this.daliy_mailForm.dept_id = this.user_data.dept_id;\r\n    }\r\n    if (\r\n      this.role_id == 5 ||\r\n      this.user_data.dept_id != \"\" ||\r\n      this.user_data.dept_id\r\n    ) {\r\n      this.getDepartment().then(({ data }) => {\r\n        if (data.success) {\r\n          this.deptSingel = data.data;\r\n          this.monthly_button = this.deptSingel.monthly_date_range.status;\r\n          console.log(this.deptSingel.monthly_date_range.status);\r\n        }\r\n      });\r\n    }\r\n    this.getDept();\r\n    this.tabs = [\r\n      { id: \"work_with_plan\", name: \" Work with plan\" },\r\n      { id: \"without_plan\", name: \"Without plan\" },\r\n      { id: \"undone\", name: \"Undone\" },\r\n      { id: \"others\", name: \"Others\" },\r\n      //{'id' : 'single_page' , 'name' : 'Single Page' },\r\n      //{'id' : 'wing_report' , 'name' : 'Wing Report' }\r\n    ];\r\n    this.getDepartment();\r\n  },\r\n  methods: {\r\n    hide_pop_permission() {\r\n      this.$modal.hide(\"popup-permission\");\r\n    },\r\n    show_pop_permission(item) {\r\n      this.mail_comment = item;\r\n      console.log(this.mail_comment);\r\n      this.$modal.show(\"popup-permission\");\r\n    },\r\n    hide_pop() {\r\n      this.$modal.hide(\"popup-singel\");\r\n    },\r\n    show_pop(item) {\r\n      this.mail_comment = item;\r\n      console.log(this.mail_comment);\r\n      this.$modal.show(\"popup-singel\");\r\n    },\r\n    hide_pop_singel() {\r\n      this.$modal.hide(\"singel\");\r\n    },\r\n    singenPage() {\r\n      this.$modal.show(\"singel\");\r\n    },\r\n    hide_pop_singel2() {\r\n      this.$modal.hide(\"singel2\");\r\n    },\r\n    singenPage2() {\r\n      this.$modal.show(\"singel2\");\r\n    },\r\n    tabsSet(id, index) {\r\n      this.report_type = id;\r\n      this.type_select = index;\r\n    },\r\n    fileDownload(id) {\r\n      window.open(this.api_url + \"monthly_report_download/\" + id, \"_blank\");\r\n    },\r\n    open_file(id) {\r\n      console.log(id);\r\n    },\r\n    async row_delete(id) {\r\n      await axios\r\n        .delete(this.api_url + \"monthly_reports/\" + id, {\r\n          headers: {\r\n            \"Content-Type\": \"application/json\",\r\n            Authorization: this.token ? `Bearer ${this.token}` : \"\",\r\n          },\r\n        })\r\n        .then((res) => {\r\n          console.log(res);\r\n\r\n          if (res.data.success) {\r\n            this.$toasted.show(res.data.message, {\r\n              theme: \"bubble\",\r\n              duration: 5000,\r\n              position: \"bottom-right\",\r\n            });\r\n          }\r\n          this.getItems();\r\n          //loader.hide();\r\n        });\r\n    },\r\n    async delete_row(id) {\r\n      this.$swal({\r\n        title: \"Are you sure?\",\r\n        text: \"Are you sure you want to delete?\",\r\n        icon: \"warning\",\r\n        buttons: true,\r\n        dangerMode: true,\r\n      }).then((data) => {\r\n        if (data) {\r\n          this.row_delete(id);\r\n        } else {\r\n          // loader.hide();\r\n          this.$swal(\"Your task status is not change!\");\r\n        }\r\n      });\r\n\r\n      console.log(id);\r\n      let loader = this.$loading.show();\r\n      try {\r\n        await axios\r\n          .delete(this.api_url + \"daily_schedules/\" + id, {\r\n            headers: {\r\n              \"Content-Type\": \"application/json\",\r\n              Authorization: this.token ? `Bearer ${this.token}` : \"\",\r\n            },\r\n          })\r\n          .then(({ res }) => {\r\n            if (res.data.success) {\r\n              this.$toasted.show(res.data.message, {\r\n                theme: \"bubble\",\r\n                duration: 5000,\r\n                position: \"bottom-right\",\r\n              });\r\n            }\r\n            loader.hide();\r\n          });\r\n      } catch (error) {\r\n        loader.hide();\r\n      }\r\n    },\r\n    async monthly_permission() {\r\n      try {\r\n        let loader = this.$loading.show();\r\n        this.daliy_mailForm.item = this.mail_comment;\r\n        this.daliy_mailForm\r\n          .post(this.api_url + \"monthly_report_permission\", {\r\n            headers: {\r\n              \"Content-Type\": \"application/json\",\r\n              Authorization: this.token ? `Bearer ${this.token}` : \"\",\r\n            },\r\n          })\r\n          .then(\r\n            (res) => {\r\n              if (res.data.success) {\r\n                this.$toasted.show(res.data.message, {\r\n                  theme: \"bubble\",\r\n                  duration: 5000,\r\n                  position: \"bottom-right\",\r\n                });\r\n              }\r\n              loader.hide();\r\n              // this.$router.push('/daily_work');\r\n            },\r\n            (error) => {\r\n              console.log(error);\r\n              loader.hide();\r\n            }\r\n          );\r\n      } catch (error) {\r\n        // loader.hide();\r\n        console.log(error);\r\n      }\r\n    },\r\n    comment() {\r\n      try {\r\n        let loader = this.$loading.show();\r\n   