rapper\">\r\n        <div class=\"content-header row\">\r\n          <div class=\"content-header-left col-12 mb-1 mt-0\">\r\n            <div class=\"row breadcrumbs-top\">\r\n              <div class=\"col-sm-9\">\r\n                <div class=\"breadcrumb-wrapper col-9\">\r\n                  <ol class=\"breadcrumb p-0 mb-0\">\r\n                    <li class=\"breadcrumb-item\">\r\n                      <router-link :to=\"{ path: '/' }\"><i class=\"bx bx-home-alt\"></i>\r\n                      </router-link>\r\n                    </li>\r\n                    <li class=\"breadcrumb-item active\">KRA , KPI and MOS </li>\r\n                  </ol>\r\n                </div>\r\n              </div>\r\n              <div class=\"col-sm-3\">\r\n                <!-- <router-link class=\"btn btn-primary add-btn\" :to=\"{ path: '/add_daily_work' }\"> <i class=\"bx bx-add-alt\"></i> Add daily work </router-link> -->\r\n              </div>\r\n            </div>\r\n          </div>\r\n        </div>\r\n        <div class=\"content-body\">\r\n          <section id=\"basic-datatable\">\r\n            <div class=\"users-list-filter px-1\">\r\n              <div class=\"row border rounded py-2 mb-2\">\r\n                <div class=\"col-sm-6 col-lg-2\" v-if=\"deptItems.length > 1\">\r\n                  <label for=\"users-list-verified\">Department</label>\r\n                  <fieldset class=\"form-group\">\r\n                    <select class=\"form-control\" v-on:change=\"getItems()\" v-model=\"filterForm.dept_id\"\r\n                      id=\"users-list-verified\">\r\n                      <option value=\"\">Select One</option>\r\n                      <option v-for=\"row in deptItems\" :key=\"row.id\" :value=\"row.id\">\r\n                        {{ row.name }}\r\n                      </option>\r\n                    </select>\r\n                  </fieldset>\r\n                </div>\r\n\r\n                <div class=\"ccol-sm-6 col-lg-2\" v-if=\"role_id == 5 || role_id == 6\">\r\n                  <label for=\"users-list-verified\">Wings</label>\r\n                  <fieldset class=\"form-group\">\r\n                    <select class=\"form-control\" v-on:change=\"changeEmployee()\" v-model=\"filterForm.wing_id\"\r\n                      id=\"users-list-verified\">\r\n                      <option value=\"\">Select One</option>\r\n                      <option v-for=\"row in WingsItems\" :key=\"row.id\" :value=\"row.id\">\r\n                        {{ row.wing_title }}\r\n                      </option>\r\n                    </select>\r\n                  </fieldset>\r\n                </div>\r\n                <div class=\"col-sm-6 col-lg-2\" v-if=\" role_id == 5 || role_id == 6 \">\r\n                  <label for=\"users-list-verified\">Employee</label>\r\n                  <fieldset class=\"form-group\">\r\n                    <select class=\"form-control\" v-on:change=\"getItems()\" v-model=\"filterForm.user_id\"\r\n                      id=\"users-list-verified\">\r\n                      <option value=\"\">Select One</option>\r\n                      <option v-for=\"row in employeeItem\" :key=\"row.id\" :value=\"row.id\">\r\n                        {{ row.employee_id ?   row.employee_id + ' : ' : ''  }} {{ row.name }}\r\n                      </option>\r\n                    </select>\r\n                  </fieldset>\r\n                </div>\r\n                <!---FILTER-->\r\n                <div class=\"col-sm-6\">\r\n                  <div class=\"form-inline justify-content-center row\" style=\"padding-top: 10px\">\r\n                    <label class=\"mb-2 mr-sm-2 col-1\">Show <strong>KRA</strong>\r\n                      <input type=\"checkbox\" checked=\"\" value=\"0\" v-model=\"filterForm.show_kra\" /></label>\r\n                    <label class=\"mb-2 mr-sm-2 col-1\">Show <strong>KPI</strong>\r\n                      <input type=\"checkbox\" checked=\"\" value=\"0\" v-model=\"filterForm.show_kpi\" /></label>\r\n                    <label class=\"mb-2 mr-sm-2 col-1\">Show <strong>MOS</strong>\r\n                      <input type=\"checkbox\" checked=\"\" value=\"0\" v-model=\"filterForm.show_mos\" /></label>\r\n\r\n                    <label class=\"mb-2 mr-sm-2 col-1\">\r\n                      Download\r\n                      <vue-excel-xlsx :data=\"dataItemExel\" :columns=\"columns\" :filename=\"'KRA KPI List'\"\r\n                        :sheetname=\"'Target'\">\r\n                        <p class=\"bx bxs-cloud-download\"></p>\r\n                      </vue-excel-xlsx>\r\n                    </label>\r\n                  </div> \r\n                </div>\r\n              </div>\r\n            </div>\r\n            <div class=\"row\">\r\n              <div class=\"col-12\">\r\n                <div class=\"card\">\r\n                  <div class=\"card-content\">\r\n                    <div class=\"card-body card-dashboard\">\r\n                      \r\n                      <div class=\"table-responsive\">\r\n                        <!-- <br> \r\n                        <br> -->\r\n                      <h3>KRA , KPI and MOS </h3>\r\n                      <br>\r\n                      <br>\r\n                        <table class=\"table table-bordered table-sm\">\r\n                          <thead class=\"thead-dark\">\r\n                            <tr>\r\n                              <th v-if=\"filterForm.show_kra == 1\">KRA</th>\r\n                              <th v-if=\"filterForm.show_kra == 1\">Weightage</th>\r\n                              <th v-if=\"filterForm.show_kpi == 1\">KPI</th>\r\n                              <th v-if=\"filterForm.show_mos == 1\">MOS</th>\r\n                              <th>Jan</th>\r\n                              <th>Feb</th>\r\n                              <th>Mar</th>\r\n                              <th>Apr</th>\r\n                              <th>May</th>\r\n                              <th>Jun</th>\r\n                              <th>Jul</th>\r\n                              <th>Aug</th>\r\n                              <th>Sep</th>\r\n                              <th>Oct</th>\r\n                              <th>Nov</th>\r\n                              <th>Dec</th>\r\n                              <th v-if=\"role_id == 5 || role_id == 6 || role_id == 7 || role_id == 10\">\r\n                                Action\r\n                              </th>\r\n                            </tr>\r\n                          </thead>\r\n                          <tbody>\r\n                            <template v-for=\"(item, index) in items\">\r\n                              <tr :key=\"item.id\">\r\n                                <td :rowspan=\"rowVisible(index, item, 'kra')\" v-if=\"\r\n                                    filterForm.show_kra == 1 &&\r\n                                    (items[index > 0 ? index - 1 : 0].kra_id !=\r\n                                      item.kra_id ||\r\n                                      index == 0)\r\n                                  \">\r\n                                  {{\r\n                                  item.krajoin ? item.krajoin.kra_name : \"\"\r\n                                  }}\r\n                                </td>\r\n                                <td :rowspan=\"rowVisible(index, item, 'kra')\" v-if=\"\r\n                                    filterForm.show_kra == 1 &&\r\n                                    (items[index > 0 ? index - 1 : 0].kra_id !=\r\n                                      item.kra_id ||\r\n                                      index == 0)\r\n                                  \">\r\n                                  {{\r\n                                  item.krajoin ? item.krajoin.kra_weight : \"\"\r\n                                  }}\r\n                                </td>\r\n                                <td :rowspan=\"rowVisible(index, item, 'kpi')\" v-if=\"\r\n                                    filterForm.show_kpi == 1 &&\r\n                                    (items[index > 0 ? index - 1 : 0].kpi_id !=\r\n                                      item.kpi_id ||\r\n                                      index == 0)\r\n                                  \">\r\n                                  {{\r\n                                  item.kpijoin ? item.kpijoin.kpi_name : \"\"\r\n                                  }}\r\n                                </td>\r\n                                <!-- <td v-if=\"filterForm.show_mos==1\">{{ item.mos_name }}  ({{ Number(moduleTotal(item)).toFixed(2) }}) </td> -->\r\n                                <td v-if=\"filterForm.show_mos == 1\">\r\n                                  {{ item.mos_name }}\r\n                                </td>\r\n                                <!-- <td :rowspan=\"item.kra_count\"\r\n                                                                    v-if=\"items[index > 0 ? index - 1 : 0 ].kra_id != item.kra_id || index ==0\">\r\n                                                                    {{ item.krajoin ? item.krajoin.kra_name : '' }}</td>\r\n                                                                <td :rowspan=\"item.kra_count\"\r\n                                                                    v-if=\"items[index > 0 ? index - 1 : 0 ].kra_id != item.kra_id || index ==0\">\r\n                                                                    {{ item.krajoin ? item.krajoin.kra_weight : '' }}\r\n                                                                </td>\r\n                                                                <td :rowspan=\"item.kpi_count\"\r\n                                                                    v-if=\"items[index > 0 ? index - 1 : 0 ].kpi_id != item.kpi_id || index ==0\">\r\n                                                                    {{ item.kpijoin ? item.kpijoin.kpi_name : '' }}</td>\r\n                                                                <td>{{ item.mos_name }}</td> -->\r\n                                <td>\r\n                                  <i v-if=\"\r\n                                      item.mostargetjoin\r\n                                        ? item.mostargetjoin.january\r\n                                        : 0 > 0\r\n                                    \" class=\"bx bx-map\"></i>\r\n                                </td>\r\n                                <td>\r\n                                  <i v-if=\"\r\n                                      item.mostargetjoin\r\n                                        ? item.mostargetjoin.february\r\n                                        : 0 > 0\r\n                                    \" class=\"bx bx-map\"></i>\r\n                                </td>\r\n                                <td>\r\n                                  <i v-if=\"\r\n                                      item.mostargetjoin\r\n                                        ? item.mostargetjoin.march\r\n                                        : 0 > 0\r\n                                    \" class=\"bx bx-map\"></i>\r\n                                </td>\r\n                                <td>\r\n                                  <i v-if=\"\r\n                                      item.mostargetjoin\r\n                                        ? item.mostargetjoin.april\r\n                                        : 0 > 0\r\n                                    \" class=\"bx bx-map\"></i>\r\n                                </td>\r\n                                <td>\r\n                                  <i v-if=\"\r\n                                      item.mostargetjoin\r\n                                        ? item.mostargetjoin.may\r\n                                        : 0 > 0\r\n                                    \" class=\"bx bx-map\"></i>\r\n                                </td>\r\n                                <td>\r\n                                  <i v-if=\"\r\n                                      item.mostargetjoin\r\n                                        ? item.mostargetjoin.june\r\n                                        : 0 > 0\r\n                                    \" class=\"bx bx-map\"></i>\r\n                                </td>\r\n                                <td>\r\n                                  <i v-if=\"\r\n                                      item.mostargetjoin\r\n                                        ? item.mostargetjoin.july\r\n                                        : 0 > 0\r\n                                    \" class=\"bx bx-map\"></i>\r\n                                </td>\r\n                                <td>\r\n                                  <i v-if=\"\r\n                                      item.mostargetjoin\r\n                                        ? item.mostargetjoin.august\r\n                                        : 0 > 0\r\n                                    \" class=\"bx bx-map\"></i>\r\n                                </td>\r\n                                <td>\r\n                                  <i v-if=\"\r\n                                      item.mostargetjoin\r\n                                        ? item.mostargetjoin.september\r\n                                        : 0 > 0\r\n                                    \" class=\"bx bx-map\"></i>\r\n                                </td>\r\n                                <td>\r\n                                  <i v-if=\"\r\n                                      item.mostargetjoin\r\n                                        ? item.mostargetjoin.october\r\n                                        : 0 > 0\r\n                                    \" class=\"bx bx-map\"></i>\r\n                                </td>\r\n                                <td>\r\n                                  <i v-if=\"\r\n                                      item.mostargetjoin\r\n                                        ? item.mostargetjoin.november\r\n                                        : 0 > 0\r\n                                    \" class=\"bx bx-map\"></i>\r\n                                </td>\r\n                                <td>\r\n                                  <i v-if=\"\r\n                                      item.mostargetjoin\r\n                                        ? item.mostargetjoin.december\r\n                                        : 0 > 0\r\n                                    \" class=\"bx bx-map\"></i>\r\n                                </td>\r\n                                <td v-if=\"role_id == 5 || role_id == 6 || role_id == 7 || role_id == 10 \">\r\n                                  <div class=\"dropup\" v-if=\"p_data\">\r\n                                    <span class=\"\r\n                                        bx bx-dots-vertical-rounded\r\n                                        font-medium-3\r\n                                        dropdown-toggle\r\n                                        nav-hide-arrow\r\n                                        cursor-pointer\r\n                                      \" data-toggle=\"dropdown\" aria-haspopup=\"true\" aria-expanded=\"false\" role=\"menu\">\r\n                                    </span>\r\n                                    <div   class=\"dropdown-menu dropdown-menu-right\">\r\n                                      <!--- KRA EDIT -->\r\n                                      <a @click=\"editKra(item)\" class=\"dropdown-item\">\r\n                                        <i class=\"bx bx-edit-alt mr-1\"> </i>\r\n                                        KRA Edit\r\n                                      </a>\r\n\r\n                                      <!--- KRA DELETE -->\r\n                                      <a @click=\"delete_kra(item.kra_id)\" class=\"dropdown-item\">\r\n                                        <i class=\"bx bx-trash mr-1\"> </i>\r\n                                        KRA Delete\r\n                                      </a>\r\n\r\n                                      <!--- KPI ADD -->\r\n                                      <a @click=\"addKpi(item)\" class=\"dropdown-item\">\r\n                                        <i class=\"bx bx-edit-alt mr-1\"> </i>\r\n                                        KPI Add\r\n                                      </a>\r\n\r\n                                      <!--- KPI EDIT -->\r\n                                      <a @click=\"editKpi(item)\" class=\"dropdown-item\">\r\n                                        <i class=\"bx bx-edit-alt mr-1\"> </i>\r\n                                        KPI Edit\r\n                                      </a>\r\n\r\n                                      <!--- KPI DELETE -->\r\n                                      <a @click=\"delete_kpi(item.kpi_id)\" class=\"dropdown-item\">\r\n                                        <i class=\"bx bx-trash mr-1\"> </i>\r\n                                        KPI Delete\r\n                                      </a>\r\n\r\n                                      <!--- MOS ADD -->\r\n                                      <a @click=\"addMos(item)\" class=\"dropdown-item\">\r\n                                        <i class=\"bx bx-edit-alt mr-1\"> </i>\r\n                                        MOS Add\r\n                                      </a>\r\n\r\n                                      <!--- MOS EDIT -->\r\n                                      <a @click=\"editMos(item)\" class=\"dropdown-item\">\r\n                                        <i class=\"bx bx-edit-alt mr-1\"> </i>\r\n                                        MOS Edit\r\n                                      </a>\r\n\r\n                                      <!--- MOS DELETE -->\r\n                                      <a @click=\"delete_mos(item.id)\" class=\"dropdown-item\">\r\n                                        <i class=\"bx bx-trash mr-1\"> </i>\r\n                                        MOS Delete\r\n                                      </a>\r\n\r\n                                      <!-- <a class=\"dropdown-item\" @click=\"add_kpi(item )\"><i class=\"bx bxs-comment-add mr-1\"></i> Add || Edit KPI </a>   -->\r\n                                      <router-link class=\"dropdown-item\" :to=\"{\r\n                                          path:\r\n                                            '/measure_of_success/' +\r\n                                            item.kpi_id,\r\n                                        }\">\r\n                                        <i class=\"bx bx-edit-alt mr-1\"></i> MOS\r\n                                        Target\r\n                                      </router-link>\r\n                                      <a v-if=\"item.krajoin.role_id == 6 || item.krajoin.role_id == 7\" @click=\"AchiTarget(item)\" class=\"dropdown-item\">\r\n                                        <i class=\"bx bx-edit-alt mr-1\"> </i>\r\n                                        Yearly Target Achievement\r\n                                      </a> \r\n                                    </div>\r\n                                  </div>\r\n\r\n                                  <!-- <button class=\"btn btn-success btn-sm\" > Add || Edit KPI  </button>\r\n                                                                    <router-link class=\"btn btn-primary add-btn\" :to=\"{ path: '/measure_of_success/'+ item.kpi_id }\"> <i class=\"bx bx-add-alt\"></i>MOS  </router-link> \r\n                                                                     <a class=\"btn btn-primary btn-sm\" href=\"https://bpt.ssgbd.com/value_fwr/125/378\">FWR</a>   -->\r\n                                </td>\r\n                              </tr>\r\n                            </template>\r\n                          </tbody>\r\n                        </table>\r\n                      </div>\r\n                    </div>\r\n                  </div>\r\n                </div>\r\n              </div>\r\n            </div>\r\n          </section>\r\n          <modal width=\"60%\" height=\"70%\" style=\"padding: 50px\" name=\"popup-singel\">\r\n            <i @click=\"hide_pop()\" class=\"bx bx-x-circle x-circle\"></i>\r\n            <div class=\"app-content\">\r\n              <div class=\"card\">\r\n                <table class=\"table table-bordered table-striped table-sm\">\r\n                  <tbody>\r\n                    <tr>\r\n                      <td>KRA Name</td>\r\n                      <td>{{ item.krajoin ? item.krajoin.kra_name : \"\" }}</td>\r\n                    </tr>\r\n                    <tr>\r\n                      <td>KPI Name</td>\r\n                      <td>{{ item.kpijoin ? item.kpijoin.kpi_name : \"\" }}</td>\r\n                    </tr>\r\n                    <tr>\r\n                      <td>MOS Name</td>\r\n                      <td>{{ item.mos_name }}</td>\r\n                    </tr>\r\n                  </tbody>\r\n                </table>\r\n              </div>\r\n            </div>\r\n          </modal>\r\n\r\n          <!-- EDIT KRA MODAL -->\r\n          <modal width=\"60%\" height=\"70%\" style=\"padding: 50px\" name=\"kraedit\">\r\n            <i @click=\"hide_pop()\" class=\"bx bx-x-circle x-circle\"></i>\r\n            <div class=\"app-content\">\r\n              <div class=\"card\">\r\n                <form @submit.prevent=\"updateKra()\">\r\n                  <div class=\"card-body\">\r\n                    <div class=\"form-group\">\r\n                      <div class=\"row\">\r\n                        <div class=\"col-md-12\">\r\n                          <div class=\"form-group\">\r\n                            <label class=\"text-gray-600 font-semibold text-lg\">KRA Name\r\n                            </label>\r\n                            <div class=\"controls\">\r\n                              <input type=\"hidden\" v-model=\"kra_id\" />\r\n                              <input type=\"text\" v-model=\"kra_name\" class=\"form-control\" placeholder=\"KRA Name\" />\r\n                            </div>\r\n                          </div>\r\n                        </div>\r\n                        <div class=\"col-md-12\">\r\n                          <div class=\"form-group\">\r\n                            <label class=\"text-gray-600 font-semibold text-lg\">KRA Weightage\r\n                            </label>\r\n                            <div class=\"controls\">\r\n                              <input type=\"text\" v-model=\"kra_weight\" class=\"form-control\"\r\n                                placeholder=\"KRA WEIGHTAGE\" />\r\n                            </div>\r\n                          </div>\r\n                        </div>\r\n                      </div>\r\n                    </div>\r\n                    <button type=\"submit\" class=\"btn btn-primary\">\r\n                      Update\r\n                    </button>\r\n                  </div>\r\n                </form>\r\n              </div>\r\n            </div>\r\n          </modal>\r\n\r\n          <!-- EDIT KPI MODAL -->\r\n          <modal width=\"60%\" height=\"70%\" style=\"padding: 50px\" name=\"kpiedit\">\r\n            <i @click=\"hide_pop()\" class=\"bx bx-x-circle x-circle\"></i>\r\n            <div class=\"app-content\">\r\n              <div class=\"card\">\r\n                <form @submit.prevent=\"updateKpi()\">\r\n                  <div class=\"card-body\">\r\n                    <div class=\"form-group\">\r\n                      <div class=\"row\">\r\n                        <div class=\"col-md-12\">\r\n                          <div class=\"form-group\">\r\n                            <label class=\"text-gray-600 font-semibold text-lg\">KPI Name\r\n                            </label>\r\n                            <div class=\"controls\">\r\n                              <inpu