                  <div class=\"controls\">\r\n                              <input type=\"hidden\" v-model=\"kra_id\" />\r\n                              <input type=\"text\" v-model=\"kpi_name\" class=\"form-control\" placeholder=\"KPI Name\" />\r\n                            </div>\r\n                          </div>\r\n                        </div>\r\n                        <div class=\"col-md-12\">\r\n                          <div class=\"form-group\">\r\n                            <label class=\"text-gray-600 font-semibold text-lg\">KPI Weightage\r\n                            </label>\r\n                            <div class=\"controls\">\r\n                              <input type=\"text\" v-model=\"kpi_weight\" class=\"form-control\"\r\n                                placeholder=\"KPI WEIGHTAGE\" />\r\n                            </div>\r\n                          </div>\r\n                        </div>\r\n                      </div>\r\n                    </div>\r\n                    <button type=\"submit\" class=\"btn btn-primary\">\r\n                      Add New\r\n                    </button>\r\n                  </div>\r\n                </form>\r\n              </div>\r\n            </div>\r\n          </modal>\r\n\r\n          <!-- ADD NEW MOS -->\r\n          <modal width=\"60%\" height=\"70%\" style=\"padding: 50px\" name=\"mosadd\">\r\n            <i @click=\"hide_pop()\" class=\"bx bx-x-circle x-circle\"></i>\r\n            <div class=\"app-content\">\r\n              <div class=\"card\">\r\n                <form @submit.prevent=\"addNewMos()\">\r\n                  <div class=\"card-body\">\r\n                    <div class=\"form-group\">\r\n                      <div class=\"row\">\r\n                        <div class=\"col-md-12\">\r\n                          <div class=\"form-group\">\r\n                            <label class=\"text-gray-600 font-semibold text-lg\">MOS Name\r\n                            </label>\r\n                            <div class=\"controls\">\r\n                              <input type=\"hidden\" v-model=\"kra_id\" />\r\n                              <input type=\"hidden\" v-model=\"kpi_id\" />\r\n                              <input type=\"text\" v-model=\"mos_name\" class=\"form-control\" placeholder=\"MOS Name\" />\r\n                            </div>\r\n                          </div>\r\n                        </div>\r\n                        <div class=\"col-md-12\">\r\n                          <div class=\"form-group\">\r\n                            <label class=\"text-gray-600 font-semibold text-lg\">MOS Weightage\r\n                            </label>\r\n                            <div class=\"controls\">\r\n                              <input type=\"text\" v-model=\"mos_weight\" class=\"form-control\"\r\n                                placeholder=\"MOS WEIGHTAGE\" />\r\n                            </div>\r\n                          </div>\r\n                        </div>\r\n                      </div>\r\n                    </div>\r\n                    <button type=\"submit\" class=\"btn btn-primary\">\r\n                      Add New\r\n                    </button>\r\n                  </div>\r\n                </form>\r\n              </div>\r\n            </div>\r\n          </modal>\r\n\r\n          <!-- EDIT MOS MODAL -->\r\n          <modal width=\"60%\" height=\"70%\" style=\"padding: 50px\" name=\"mosedit\">\r\n            <i @click=\"hide_pop()\" class=\"bx bx-x-circle x-circle\"></i>\r\n            <div class=\"app-content\">\r\n              <div class=\"card\">\r\n                <form @submit.prevent=\"updateMos()\">\r\n                  <div class=\"card-body\">\r\n                    <div class=\"form-group\">\r\n                      <div class=\"row\">\r\n                        <div class=\"col-md-12\">\r\n                          <div class=\"form-group\">\r\n                            <label class=\"text-gray-600 font-semibold text-lg\">MOS Name\r\n                            </label>\r\n                            <div class=\"controls\">\r\n                              <input type=\"hidden\" v-model=\"mos_id\" />\r\n                              <input type=\"hidden\" v-model=\"kpi_id\" />\r\n                              <input type=\"text\" v-model=\"mos_name\" class=\"form-control\" placeholder=\"MOS Name\" />\r\n                            </div>\r\n                          </div>\r\n                        </div>\r\n                        <div class=\"col-md-12\">\r\n                          <div class=\"form-group\">\r\n                            <label class=\"text-gray-600 font-semibold text-lg\">MOS Weightage\r\n                            </label>\r\n                            <div class=\"controls\">\r\n                              <input type=\"text\" v-model=\"mos_weight\" class=\"form-control\"\r\n                                placeholder=\"KPI WEIGHTAGE\" />\r\n                            </div>\r\n                          </div>\r\n                        </div>\r\n                      </div>\r\n                    </div>\r\n                    <button type=\"submit\" class=\"btn btn-primary\">\r\n                      Update\r\n                    </button>\r\n                  </div>\r\n                </form>\r\n              </div>\r\n            </div>\r\n          </modal>\r\n          <!-- Yearly Achiv and Target  -->\r\n          <modal width=\"60%\" height=\"70%\" style=\"padding: 50px\" name=\"achi_target\">\r\n            <i @click=\"hide_pop()\" class=\"bx bx-x-circle x-circle\"></i>\r\n            <div class=\"app-content\">\r\n              <div class=\"card\">\r\n                <form @submit.prevent=\"updateYearlyAchiv()\">\r\n                \r\n                  <div class=\"card-body\">\r\n                    <div class=\"form-group\">\r\n                      <div class=\"row\">\r\n                        <div class=\"col-md-12\">\r\n                          <h4>MOS : {{ item.mos_name }}( <strong>W:{{ item.weightage}}</strong> )</h4>\r\n                          <div class=\"form-group\">\r\n                            <label class=\"text-gray-600 font-semibold text-lg\">Target \r\n                            </label>\r\n                           \r\n                            <div class=\"controls\"> \r\n                              <input type=\"text\" v-model=\"mosatarget.total\" class=\"form-control\" placeholder=\"Target\" />\r\n                            </div>\r\n                          </div>\r\n                        </div>\r\n                        <div class=\"col-md-12\">\r\n                          <div class=\"form-group\">\r\n                            <label class=\"text-gray-600 font-semibold text-lg\">Achievement\r\n                            </label>\r\n                            <div class=\"controls\">\r\n                              <input type=\"text\" v-model=\"mosachievement.total\" class=\"form-control\"\r\n                                placeholder=\"Achievement\" />\r\n                            </div>\r\n                          </div>\r\n                        </div>\r\n                      </div>\r\n                    </div>\r\n                    <button type=\"submit\" class=\"btn btn-primary\">\r\n                      Update\r\n                    </button>\r\n                  </div>\r\n                </form>\r\n              </div>\r\n            </div>\r\n          </modal>\r\n\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n</template>\r\n\r\n\r\n\r\n<script>\r\n  import axios from \"../../axios_instance\";\r\n  import { Form } from \"vform\";\r\n  // import JsonExcel from \"vue-json-excel\"\r\n  export default {\r\n    props: {},\r\n    components: {\r\n      // \"downloadExcel\": JsonExcel\r\n      //VueExcelXlsx\r\n      // VueRecaptcha, facebookLogin\r\n    },\r\n    data() {\r\n      return {\r\n        //Jan\tFeb\tMar\tApr\tMay\tJun\tJul\tAug\tSep\tOct\tNov\tDec\r\n        columns: [\r\n          {\r\n            label: \"KRA\",\r\n            field: \"krajoin\",\r\n            dataFormat: this.kraName,\r\n            rowspan: 4,\r\n          },\r\n          {\r\n            label: \"KRA Weightage\",\r\n            field: \"krajoin\",\r\n            dataFormat: this.weightageValue,\r\n          },\r\n          {\r\n            label: \"KPI\",\r\n            field: \"kpijoin\",\r\n            dataFormat: this.kpiName,\r\n          },\r\n          {\r\n            label: \"KPI Weightage\",\r\n            field: \"kpijoin\",\r\n            dataFormat: this.kpiweightageValue,\r\n          },\r\n          {\r\n            label: \"MOS\",\r\n            field: \"mos_name\",\r\n          },\r\n          {\r\n            label: \"MOS Weightage\",\r\n            field: \"weightage\",\r\n          },\r\n          {\r\n            label: \"Jan\",\r\n            field: \"mostargetjoin\",\r\n            dataFormat: this.targetJan,\r\n          },\r\n          {\r\n            label: \"Fen\",\r\n            field: \"mostargetjoin\",\r\n            dataFormat: this.targetFeb,\r\n          },\r\n          {\r\n            label: \"Mar\",\r\n            field: \"mostargetjoin\",\r\n            dataFormat: this.targetMar,\r\n          },\r\n          {\r\n            label: \"Apr\",\r\n            field: \"mostargetjoin\",\r\n            dataFormat: this.targetApr,\r\n          },\r\n          {\r\n            label: \"May\",\r\n            field: \"mostargetjoin\",\r\n            dataFormat: this.targetMay,\r\n          },\r\n          {\r\n            label: \"Jun\",\r\n            field: \"mostargetjoin\",\r\n            dataFormat: this.targetJun,\r\n          },\r\n          {\r\n            label: \"Jul\",\r\n            field: \"mostargetjoin\",\r\n            dataFormat: this.targetJul,\r\n          },\r\n          {\r\n            label: \"Aug\",\r\n            field: \"mostargetjoin\",\r\n            dataFormat: this.targetAug,\r\n          },\r\n          {\r\n            label: \"Sep\",\r\n            field: \"mostargetjoin\",\r\n            dataFormat: this.targetSep,\r\n          },\r\n          {\r\n            label: \"Oct\",\r\n            field: \"mostargetjoin\",\r\n            dataFormat: this.targetOct,\r\n          },\r\n          {\r\n            label: \"Nov\",\r\n            field: \"mostargetjoin\",\r\n            dataFormat: this.targetNov,\r\n          },\r\n          {\r\n            label: \"Dec\",\r\n            field: \"mostargetjoin\",\r\n            dataFormat: this.targetDec,\r\n          },\r\n        ],\r\n        dataItemExel: [],\r\n\r\n        json_fields: {\r\n          \"Complete name\": \"name\",\r\n          City: \"city\",\r\n          Telephone: \"phone.mobile\",\r\n          \"Telephone 2\": {\r\n            field: \"phone.landline\",\r\n            callback: (value) => {\r\n              return `Landline Phone - ${value}`;\r\n            },\r\n          },\r\n        },\r\n        json_data: [\r\n          {\r\n            name: \"Tony Peña\",\r\n            city: \"New York\",\r\n            country: \"United States\",\r\n            birthdate: \"1978-03-15\",\r\n            phone: {\r\n              mobile: \"1-541-754-3010\",\r\n              landline: \"(541) 754-3010\",\r\n            },\r\n          },\r\n          {\r\n            name: \"Thessaloniki\",\r\n            city: \"Athens\",\r\n            country: \"Greece\",\r\n            birthdate: \"1987-11-23\",\r\n            phone: {\r\n              mobile: \"+1 855 275 5071\",\r\n              landline: \"(2741) 2621-244\",\r\n            },\r\n          },\r\n        ],\r\n        json_meta: [\r\n          [\r\n            {\r\n              key: \"charset\",\r\n              value: \"utf-8\",\r\n            },\r\n          ],\r\n        ],\r\n        p_data : \"\",\r\n        base_url: window.base_url,\r\n        api_url: window.api_url,\r\n        token: this.$localStorage.get(\"d_token\"),\r\n        user_data: JSON.parse(this.$localStorage.get(\"user\")),\r\n        role_id: \"\",\r\n        items: [],\r\n        item: [],\r\n        mosachievement : [],\r\n        mosatarget : [],\r\n        deptItems: [],\r\n        ingsItems: [],\r\n        employeeItem: [],\r\n        filterForm: new Form({\r\n          dept_id: this.$route.query.dept_id ? this.$route.query.dept_id : \"\",\r\n          wing_id: \"\",\r\n          user_id: \"\",\r\n          kra_id: this.$route.query.kra_id ? this.$route.query.kra_id : \"\",\r\n          kpi_id: \"\",\r\n          quarter: this.$route.query.quarter ? this.$route.query.quarter : \"\",\r\n          month: this.$route.query.month ? this.$route.query.month : \"\",\r\n          show_kra: 1,\r\n          show_kpi: 1,\r\n          show_mos: 1,\r\n          show_yachi: 1,\r\n        }),\r\n        kpiForm: new Form({\r\n          dept_id: \"\",\r\n        }),\r\n\r\n        status: \"\",\r\n\r\n        year: this.$localStorage.get(\"year\"),\r\n\r\n        //KRA INITIAL DATA\r\n        kra_id: \"\",\r\n        kra_name: \"\",\r\n        kra_weight: \"\",\r\n        editKraForm: new Form({}),\r\n\r\n        //KPOI INITIAL DATA\r\n        kpi_id: \"\",\r\n        kpi_name: \"\",\r\n        kpi_weight: \"\",\r\n        editKpiForm: new Form({}),\r\n        addKpiForm: new Form({}),\r\n\r\n        //MOS INITIAL DATA\r\n        mos_id: \"\",\r\n        mos_name: \"\",\r\n        mos_weight: \"\",\r\n        editMosForm: new Form({}),\r\n        addMosForm: new Form({}),\r\n      };\r\n    },\r\n    created() {\r\n      this.role_id = this.user_data.role_id;\r\n      this.filterForm.dept_id = this.user_data.dept_id;\r\n      if (this.filterForm.dept_id) {\r\n        this.getWing();\r\n        this.filterForm.wing_id = this.user_data.wing_id ? this.user_data.wing_id : \"\";\r\n      }\r\n      if (\r\n        this.role_id == 1 ||\r\n        this.role_id == 2 ||\r\n        this.role_id == 3 ||\r\n        this.role_id == 5 ||\r\n        this.role_id == 4\r\n      ) {\r\n        //this.getDept();\r\n        this.getEmployee();\r\n        this.deptChange();\r\n      } else {\r\n        //this.getItems();\r\n\r\n        this.getItems();\r\n      }\r\n      this.single_permission();\r\n      // this.getItems();\r\n      //this.getDept();\r\n    },\r\n    methods: {\r\n      single_permission() {\r\n        axios\r\n          .get(this.api_url + \"single_permission\", {\r\n            headers: {\r\n              \"Content-Type\": \"application/json\",\r\n              Authorization: this.token ? `Bearer ${this.token}` : \"\",\r\n            },\r\n          })\r\n          .then((res) => {\r\n            this.p_data = res.data.data[0];\r\n           console.log('ds',this.p_data);\r\n          });\r\n      },\r\n      kpiName(value) {\r\n        return value.kpi_name;\r\n      },\r\n      weightageValue(value) {\r\n        return value.kra_weight;\r\n      },\r\n      kpiweightageValue(value) {\r\n        return value.kpi_weight;\r\n      },\r\n      kraName(value) {\r\n        return value.kra_name;\r\n      },\r\n      //Jan\tFeb\tMar\tApr\tMay\tJun\tJul\tAug\tSep\tOct\tNov\tDec\r\n      targetJan(e) {\r\n        return e.january > 0 ? e.january : \"\";\r\n      },\r\n      targetFeb(e) {\r\n        return e.february > 0 ? e.february : \"\";\r\n      },\r\n      targetMar(e) {\r\n        return e.march > 0 ? e.march : \"\";\r\n      },\r\n      targetApr(e) {\r\n        return e.april > 0 ? e.april : \"\";\r\n      },\r\n      targetMay(e) {\r\n        return e.may > 0 ? e.may : \"\";\r\n      },\r\n      targetJun(e) {\r\n        return e.june > 0 ? e.june : \"\";\r\n      },\r\n      targetJul(e) {\r\n        return e.july > 0 ? e.july : \"\";\r\n      },\r\n      targetAug(e) {\r\n        return e.august > 0 ? e.august : \"\";\r\n      },\r\n      targetSep(e) {\r\n        return e.september > 0 ? e.september : \"\";\r\n      },\r\n      targetOct(e) {\r\n        return e.october > 0 ? e.october : \"\";\r\n      },\r\n      targetNov(e) {\r\n        return e.november > 0 ? e.november : \"\";\r\n      },\r\n      targetDec(e) {\r\n        return e.december > 0 ? e.december : \"\";\r\n      },\r\n\r\n      hide_pop() {\r\n        this.$modal.hide(\"popup-singel\");\r\n        this.$modal.hide(\"kraedit\");\r\n        this.$modal.hide(\"kpiedit\");\r\n        this.$modal.hide(\"mosedit\");\r\n        this.$modal.hide(\"kpiadd\");\r\n        this.$modal.hide(\"mosadd\");\r\n        this.$modal.hide(\"achi_target\");\r\n      },\r\n      add_kpi(item) {\r\n        this.item = item;\r\n        this.$modal.show(\"popup-singel\");\r\n      },\r\n      AchiTarget(item) {\r\n        this.item = item;\r\n        this.mosachievement = item.mosachievementjoin;\r\n        this.mosatarget = item.mostargetjoin;\r\n        this.$modal.show(\"achi_target\");\r\n      },\r\n      AchiTargetHidden() {\r\n        //this.item = item;\r\n        this.$modal.hide(\"achi_target\");\r\n      },\r\n      async updateYearlyAchiv(){\r\n        let loader = this.$loading.show();\r\n       // async updateKra() {\r\n        let mosatargetData = new Form({ \r\n          total :  Number(this.mosatarget.total).toFixed(0),\r\n          type :   this.mosatarget.type,\r\n          mos_id :   this.mosatarget.mos_id,\r\n          dept_id :  this.mosatarget.dept_id, \r\n          january: this.mosatarget.total ? Number(this.mosatarget.total/12).toFixed(2) : 0,\r\n          february : this.mosatarget.total ?  Number(this.mosatarget.total/12).toFixed(2) : 0,\r\n          march : this.mosatarget.total ?  Number(this.mosatarget.total/12).toFixed(2) : 0,\r\n          april : this.mosatarget.total ?  Number(this.mosatarget.total/12).toFixed(2) : 0,\r\n          may : this.mosatarget.total ?  Number(this.mosatarget.total/12).toFixed(2) : 0,\r\n          june : this.mosatarget.total ?  Number(this.mosatarget.total/12).toFixed(2) : 0,\r\n         