                                  \r\n                                                                <td v-if=\"select_months('dec')\"  v-bind:class=\" achievement(item , 'december') >  100 ? 'gb_color_green': achievement(item , 'december') <  100  && achievement(item , 'december') > 0 ? 'gb_color_yellow' : ''\">\r\n                                                                    {{achievement(item , 'december') > 0 ?  achievement(item , 'december') + '%' : ''}}  \r\n                                                                    <i v-if=\"achievement(item , 'december') == 0 && item.mostargetjoin ? item.mostargetjoin.december : 0 > 0 \" class=\"bx bx-map\"  v-bind:class=\" colorCheck(12) == 'red' ? 'color_red': '' \"></i> \r\n                                                                </td>  \r\n                                                                <!-- <ion-icon name=\"location-outline\"></ion-icon>  -->\r\n                                                                <td>  \r\n                                                                    <div class=\"dropup\">\r\n                                                                        <span class=\"bx bx-dots-vertical-rounded font-medium-3 dropdown-toggle nav-hide-arrow cursor-pointer\" data-toggle=\"dropdown\" aria-haspopup=\"true\" aria-expanded=\"false\" role=\"menu\">\r\n                                                                        </span>\r\n                                                                        <div class=\"dropdown-menu dropdown-menu-right\"> \r\n                                                                            <router-link  v-if=\"role_id == 5 || role_id == 6\"  class=\"dropdown-item\" :to=\"{ path: '/achievement/'+ item.id }\" ><i class=\"bx bx-edit-alt mr-1\"></i>  Achievement </router-link>\r\n                                                                            <router-link class=\"dropdown-item\" :to=\"{ path: '/bpt_report_details/'+ item.kpi_id }\"  ><i class=\"bx bx-edit-alt mr-1\"></i> Details </router-link> \r\n                                                                            <router-link traget=\"_blank\" v-if=\"role_id == 5 || role_id == 6\" class=\"dropdown-item\" :to=\"{ path: '/measure_of_success/'+ item.kpi_id }\"  ><i class=\"bx bx-edit-alt mr-1\"></i> MOS Edit </router-link> \r\n                                                                        </div>\r\n                                                                    </div> \r\n \r\n                                                                </td> \r\n                                                            </tr> \r\n                                                        </template>      \r\n                                                    </tbody>\r\n                                                </table> \r\n \r\n                                            </div>\r\n                                        </div>\r\n                                    </div>\r\n                                </div>\r\n                            </div>\r\n                        </div>\r\n                    </section>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n    </template>\r\n    \r\n    <script>\r\n    import axios from \"../../axios_instance\";\r\n    import { Form } from \"vform\"; \r\n    export default {\r\n        props: {},\r\n        components: {\r\n            // VueRecaptcha, facebookLogin\r\n        },\r\n        data() {\r\n            return {\r\n                base_url: window.base_url,\r\n                api_url: window.api_url,\r\n                token: this.$localStorage.get(\"d_token\"),\r\n                user_data: JSON.parse(this.$localStorage.get(\"user\")),\r\n                role_id : '',\r\n                items: [],   \r\n                items_all: [],   \r\n                deptItems: [],   \r\n                filterForm: new Form({ \r\n                    dept_id: \"\",\r\n                    kra_id : \"\",\r\n                    kpi_id : \"\",\r\n                    quarter : \"\",\r\n                    month : \"\",\r\n                    show_kra: 1,\r\n                    show_kpi: 1,\r\n                    show_mos: 1,\r\n                    show_yachi: 1,\r\n                }),\r\n                status: '',\r\n                kraItem: [] ,  \r\n                kpiItem: [] ,  \r\n                mosItem: [] , \r\n            };\r\n        },\r\n        created() { \r\n            this.role_id = this.user_data.role_id ; \r\n            if( this.role_id == 5 || this.role_id == 6 || this.role_id == 7){\r\n            this.filterForm.dept_id =   this.user_data.dept_id ; \r\n            this.getKRA();\r\n            this.getItems(); \r\n            }else{\r\n                this.getDept();\r\n            } \r\n           \r\n        },\r\n        methods: {\r\n            countRow(index,item){\r\n                console.log(index);\r\n                console.log(item);\r\n                if(this.filterForm.month){\r\n                    return '' ;\r\n                }\r\n            },\r\n            monthChange(){\r\n                this.items =  this.items_all ;\r\n                let a =  this.items.filter(item => {\r\n                //for (let index = 0; index < this.items.length; index++) {\r\n                    let target = item.mostargetjoin ; \r\n                    //this.items.slice(0, index);\r\n                    let total =  0 ;\r\n               \r\n                    if(this.filterForm.month == 'jan'){\r\n                        total = target.january ;\r\n                    }else if(this.filterForm.month == 'feb'){ \r\n                        total = target.february ;\r\n                    }else if(this.filterForm.month == 'mar'){ \r\n                        total = target.march;\r\n                    }else if(this.filterForm.month == 'apr'){ \r\n                        total = target.april;\r\n                    }else if(this.filterForm.month == 'may'){ \r\n                        total = target.may ;\r\n                    }else if(this.filterForm.month == 'jun'){ \r\n                        total = target.june ;\r\n                    }else if(this.filterForm.month == 'jul'){ \r\n                        total = target.july ;\r\n                    }else if(this.filterForm.month == 'aug'){ \r\n                        total = target.august;\r\n                    }else if(this.filterForm.month == 'sep'){ \r\n                        total = target.september;\r\n                    }else if(this.filterForm.month == 'oct'){ \r\n                        total = target.october ;\r\n                    }else if(this.filterForm.month == 'nov'){  \r\n                        total = target.november ;\r\n                    }else if(this.filterForm.month == 'dec'){ \r\n                        total = target.december ;\r\n                    } \r\n                    console.log(total);\r\n                    return total > 0 ;\r\n \r\n                });    \r\n                console.log(this.filterForm.month);\r\n                this.items = a ;\r\n            },\r\n            rowVisible(index,item,type){\r\n                let  crount  = 0 ;\r\n                this.items.filter(row => {\r\n                    if(type == 'kra'){\r\n                        if(row.kra_id === item.kra_id ){ \r\n                            crount +=  1  ;\r\n                        }\r\n                    }else if(type == 'kpi'){\r\n                        if(row.kpi_id === item.kpi_id ){ \r\n                            crount +=  1  ;\r\n                        }\r\n                    }\r\n                   \r\n                }) \r\n                return  crount ; \r\n            },\r\n            \r\n            achievementTotal(item , target , achievement){ \r\n                if(target > 0 && achievement > 0 ){  \r\n\r\n                    if(item.mos_calculation ==0){\r\n                        return ((achievement/target)*100).toFixed()  ; \r\n                    }else if(item.mos_calculation ==1){\r\n                       \r\n                      return ((target/ achievement )*100).toFixed(2)  ;\r\n                       \r\n                    }else if(item.mos_calculation ==2){\r\n                       \r\n                       return ((achievement/target )*100).toFixed(2)  ;\r\n                    }else if(item.mos_calculation ==3){\r\n                        \r\n                       return ((target /achievement )*100).toFixed(2)  ;\r\n                    }else{\r\n                        return ((achievement/target)*100).toFixed(2)  ;\r\n                    }  \r\n                    \r\n                }else {\r\n                    return 0 ;\r\n                } \r\n            },\r\n            achievement(item , month){\r\n                let target  = item.mostargetjoin[month] ;\r\n                let achievement  = item.mosachievementjoin[month] ;\r\n                if(target > 0 && achievement > 0 ){  \r\n                    if(item.mos_calculation ==0){\r\n                        return ((achievement/target)*100).toFixed()  ; \r\n                    }else if(item.mos_calculation ==1){\r\n                       \r\n                      return ((target/ achievement )*100).toFixed(2)  ;\r\n                       \r\n                    }else if(item.mos_calculation ==2){\r\n                       \r\n                       return ((achievement/target )*100).toFixed(2)  ;\r\n                    }else if(item.mos_calculation ==3){\r\n                        \r\n                       return ((target /achievement )*100).toFixed(2)  ;\r\n                    }else{\r\n                        return ((achievement/target)*100).toFixed(2)  ;\r\n                    } \r\n                }else {\r\n                    return 0 ;\r\n                } \r\n            },\r\n            colorCheck(month_id){\r\n                var currentTime = new Date() \r\n                var month = currentTime.getMonth() + 1;\r\n                if(month_id < month  ){\r\n                    return 'red' ;\r\n                } \r\n            },\r\n            mosTotalTarget(item , type ){\r\n                let g_total  = 0 ;\r\n                //this.items =  this.items_all ;\r\n                //this.items.filter(item => {\r\n                    let total = 0;\r\n                    let target ;\r\n                    \r\n                        if( type == 'target' ){\r\n                            if(item.mostargetjoin){\r\n                                target = item.mostargetjoin ; \r\n                            }else{\r\n                                return  0; \r\n                            }\r\n                            \r\n                        }else if( type == 'achievement'){\r\n                            if(item.mosachievementjoin){\r\n                                target = item.mosachievementjoin ; \r\n                            }else{\r\n                                return 0 ;\r\n                            }\r\n                           \r\n                        }\r\n                          \r\n                            let q1 ;\r\n                            let q2 ;\r\n                            let q3;\r\n                            let q4 ;\r\n                            let q5;\r\n                            let q6 ;\r\n                            q1  = target.january + target.february + target.march ; \r\n                            q2  = target.april + target.may +  target.june ;\r\n                            q3  = target.july +  target.august + target.september ; \r\n                            q4  = target.october + target.november + target.december; \r\n                            q5  = q1 + q2 ; \r\n                            q6  = q3 + q4 ; \r\n                        if(this.filterForm.month =='' ){\r\n                            if(this.filterForm.quarter ==1 ){\r\n                                if(item.mos_calculation == 0 || item.mos_calculation == 1){ \r\n                                    total =  q1 ;\r\n                                }else{\r\n                                    total =  q1/3 ;\r\n                                } \r\n                            }else if(this.filterForm.quarter == 2){\r\n                                if(item.mos_calculation == 0 || item.mos_calculation == 1){ \r\n                                    total =  q2 ;\r\n                                }else{\r\n                                    total =  q2/3 ;\r\n                                }\r\n                            }else if(this.filterForm.quarter == 3){\r\n                                if(item.mos_calculation == 0 || item.mos_calculation == 1){ \r\n                                    total =  q3 ;\r\n                                }else{\r\n                                    total =  q3/3 ;\r\n                                } \r\n                            }else if(this.filterForm.quarter == 4){ \r\n                                if(item.mos_calculation == 0 || item.mos_calculation == 1){ \r\n                                    total =  q4 ;\r\n                                }else{\r\n                                    total =  q4/3 ;\r\n                                } \r\n                            }else if(this.filterForm.quarter == 5){\r\n                                if(item.mos_calculation == 0 || item.mos_calculation == 1){  \r\n                                    total =  q5 ;\r\n                                }else{\r\n                                    total =  q5/6 ;\r\n                                } \r\n                            \r\n                            }else if(this.filterForm.quarter == 6){ \r\n                                if(item.mos_calculation == 0 || item.mos_calculation == 1){ \r\n                                    total =  q6 ;\r\n                                }else{\r\n                                    total =  q6/6 ;\r\n                                } \r\n                            }else{\r\n                                if(item.mos_calculation == 0 || item.mos_calculation == 1){ \r\n                                    total =  (q1 + q2 + q3+ q4 ) ;\r\n                                }else{\r\n                                    total =  (q1 + q2 + q3+ q4) /12 ;\r\n                                } \r\n\r\n                            // total =  q1 + q2 + q3+ q4 ;\r\n                            }  \r\n                        }else{\r\n\r\n                    \r\n                            if(this.filterForm.month == 'jan'){\r\n                                total = target.january ;\r\n                            }else if(this.filterForm.month == 'feb'){ \r\n                                total = target.february ;\r\n                            }else if(this.filterForm.month == 'mar'){ \r\n                                total = target.march;\r\n                            }else if(this.filterForm.month == 'apr'){ \r\n                                total = target.april;\r\n                            }else if(this.filterForm.month == 'may'){ \r\n                                total = target.may ;\r\n                            }else if(this.filterForm.month == 'jun'){ \r\n                                total = target.june ;\r\n                            }else if(this.filterForm.month == 'jul'){ \r\n                                total = target.july ;\r\n                            }else if(this.filterForm.month == 'aug'){ \r\n                                total = target.august;\r\n                            }else if(this.filterForm.month == 'sep'){ \r\n                                total = target.september;\r\n                            }else if(this.filterForm.month == 'oct'){ \r\n                                total = target.october ;\r\n                            }else if(this.filterForm.month == 'nov'){  \r\n                                total = target.november ;\r\n                            }else if(this.filterForm.month == 'dec'){ \r\n                                total = target.december ;\r\n                            } \r\n                            // console.log(total);\r\n                            // return total > 0 ;\r\n                        }\r\n                        g_total += total ;\r\n                    //}\r\n                //});    \r\n                return this.amountConvert(g_total , 2 );\r\n                //return g_total ;\r\n            },\r\n            kpiTotalTarget(kpi_id , type ){\r\n                let g_total  = 0 ;\r\n                //this.items =  this.items_all ;\r\n                this.items.filter(item => {\r\n                    let total = 0;\r\n                    let target ;\r\n                    if(item.kpi_id ==kpi_id ){\r\n                        if( type == 'target' ){\r\n                             target = item.mostargetjoin ; \r\n                        }else if( type == 'achievement'){\r\n                            target = item.mosachievementjoin ; \r\n                        }\r\n                          \r\n                            let q1 ;\r\n                            let q2 ;\r\n                            let q3;\r\n                            let q4 ;\r\n                            let q5;\r\n                            let q6 ;\r\n                            q1  = target.january + target.february + target.march ; \r\n                            q2  = target.april + target.may +  target.june ;\r\n                            q3  = target.july +  target.august + target.september ; \r\n                            q4  = target.october + target.november + target.december; \r\n                            q5  = q1 + q2 ; \r\n                            q6  = q3 + q4 ; \r\n                        if(this.filterForm.month =='' ){\r\n                        