}) => {\r\n                            this.getItems();\r\n                            if (res.data.success) {\r\n                                this.$toasted.show(res.data.message, {\r\n                                    theme: \"bubble\",\r\n                                    duration: 5000,\r\n                                    position: \"bottom-right\",\r\n                                });\r\n                            }\r\n                            loader.hide();\r\n                        });\r\n                } catch (error) {\r\n                    loader.hide();\r\n                }\r\n            },\r\n            onlyNumber ($event) {\r\n                //console.log($event.keyCode); //keyCodes value\r\n                let keyCode = ($event.keyCode ? $event.keyCode : $event.which);\r\n                if ((keyCode < 48 || keyCode > 57) && keyCode !== 46) { // 46 is dot\r\n                    $event.preventDefault();\r\n                }\r\n            },\r\n            checkConditionKra( length , kpi_index , mos_index  ){ \r\n                if(kpi_index == 0 &&  mos_index == 0 ){\r\n                    return  true ;\r\n                }else{\r\n                    return  false ;\r\n                } \r\n            },\r\n            checkConditionKpi( length  , mos_index  ){ \r\n                if(mos_index == 0 ){\r\n                    return  true ;\r\n                }else{\r\n                    return  false ;\r\n                } \r\n            },\r\n            async getItems() {\r\n                \r\n                let loader = this.$loading.show();\r\n                try {\r\n                    await axios\r\n                        .get(this.api_url + \"k_p_i_s/\" + this.kpi_id, {\r\n                            headers: {\r\n                                \"Content-Type\": \"application/json\",\r\n                                Authorization: this.token ? `Bearer ${this.token}` : \"\"\r\n                            },\r\n                        })\r\n                        .then(({\r\n                            data\r\n                        }) => {\r\n                            if (data.success) {\r\n                                this.item = data.data ;\r\n                                console.log( 'this.item', this.item );\r\n                            }\r\n                            loader.hide();\r\n                        });\r\n                } catch (error) {\r\n                    loader.hide();\r\n                }\r\n            },\r\n            target(mos_item , mos_calculation){ \r\n\r\n                if(mos_calculation == 2 || mos_calculation == 3){\r\n\r\n                    if(mos_item.january > 0 &&  mos_item.february > 0 &&  mos_item.march > 0 &&  mos_item.april > 0 &&  mos_item.may > 0 &&  mos_item.june > 0 &&  mos_item.july > 0 &&  mos_item.august > 0 &&  mos_item.september > 0 &&  mos_item.october > 0 &&  mos_item.november > 0 &&  mos_item.december > 0){\r\n                        return ( Number(mos_item.january) + Number(mos_item.february) + Number(mos_item.march) + Number(mos_item.april) + Number(mos_item.may) + Number(mos_item.june) + Number(mos_item.july) + Number(mos_item.august) + Number(mos_item.september) + Number(mos_item.october) + Number(mos_item.november) + Number(mos_item.december) )/12 ; \r\n                    }else if(mos_item.january > 0 &&  mos_item.february > 0 &&  mos_item.march > 0 &&  mos_item.april > 0 &&  mos_item.may > 0 &&  mos_item.june > 0 &&  mos_item.july > 0 &&  mos_item.august > 0 &&  mos_item.september > 0 &&  mos_item.october > 0 &&  mos_item.november > 0  ){\r\n                        return ( Number(mos_item.january) + Number(mos_item.february) + Number(mos_item.march) + Number(mos_item.april) + Number(mos_item.may) + Number(mos_item.june) + Number(mos_item.july) + Number(mos_item.august) + Number(mos_item.september) + Number(mos_item.october) + Number(mos_item.november))/11 ; \r\n                    }else if(mos_item.january > 0 &&  mos_item.february > 0 &&  mos_item.march > 0 &&  mos_item.april > 0 &&  mos_item.may > 0 &&  mos_item.june > 0 &&  mos_item.july > 0 &&  mos_item.august > 0 &&  mos_item.september > 0 &&  mos_item.october > 0  ){\r\n                        return ( Number(mos_item.january) + Number(mos_item.february) + Number(mos_item.march) + Number(mos_item.april) + Number(mos_item.may) + Number(mos_item.june) + Number(mos_item.july) + Number(mos_item.august) + Number(mos_item.september) + Number(mos_item.october))/10 ; \r\n                    }else if(mos_item.january > 0 &&  mos_item.february > 0 &&  mos_item.march > 0 &&  mos_item.april > 0 &&  mos_item.may > 0 &&  mos_item.june > 0 &&  mos_item.july > 0 &&  mos_item.august > 0 &&  mos_item.september > 0 ){\r\n                        return ( Number(mos_item.january) + Number(mos_item.february) + Number(mos_item.march) + Number(mos_item.april) + Number(mos_item.may) + Number(mos_item.june) + Number(mos_item.july) + Number(mos_item.august) + Number(mos_item.september))/9 ; \r\n                    }else if(mos_item.january > 0 &&  mos_item.february > 0 &&  mos_item.march > 0 &&  mos_item.april > 0 &&  mos_item.may > 0 &&  mos_item.june > 0 &&  mos_item.july > 0 &&  mos_item.august > 0 ){\r\n                        return ( Number(mos_item.january) + Number(mos_item.february) + Number(mos_item.march) + Number(mos_item.april) + Number(mos_item.may) + Number(mos_item.june) + Number(mos_item.july) + Number(mos_item.august))/8 ; \r\n                    }else if(mos_item.january > 0 &&  mos_item.february > 0 &&  mos_item.march > 0 &&  mos_item.april > 0 &&  mos_item.may > 0 &&  mos_item.june > 0 &&  mos_item.july > 0  ){\r\n                        return ( Number(mos_item.january) + Number(mos_item.february) + Number(mos_item.march) + Number(mos_item.april) + Number(mos_item.may) + Number(mos_item.june) + Number(mos_item.july))/7 ; \r\n                    }else if(mos_item.january > 0 &&  mos_item.february > 0 &&  mos_item.march > 0 &&  mos_item.april > 0 &&  mos_item.may > 0 &&  mos_item.june > 0 ){\r\n                        return ( Number(mos_item.january) + Number(mos_item.february) + Number(mos_item.march) + Number(mos_item.april) + Number(mos_item.may) + Number(mos_item.june))/6 ; \r\n                    }else if(mos_item.january > 0 &&  mos_item.february > 0 &&  mos_item.march > 0 &&  mos_item.april > 0 &&  mos_item.may > 0){\r\n                        return ( Number(mos_item.january) + Number(mos_item.february) + Number(mos_item.march) + Number(mos_item.april) + Number(mos_item.may))/ 5; \r\n                    }else if(mos_item.january > 0 &&  mos_item.february > 0 &&  mos_item.march > 0 &&  mos_item.april > 0 ){\r\n                        return ( Number(mos_item.january) + Number(mos_item.february) + Number(mos_item.march) + Number(mos_item.april))/ 4; \r\n                    }else if(mos_item.january > 0 &&  mos_item.february > 0 &&  mos_item.march >  0 ){\r\n                        return ( Number(mos_item.january) + Number(mos_item.february) + Number(mos_item.march))/ 3; \r\n                    }else if(mos_item.january > 0 &&  mos_item.february > 0 ){\r\n                        return ( Number(mos_item.january) + Number(mos_item.february) )/ 2; \r\n                    }else if(mos_item.january > 0 ){\r\n                        return ( Number(mos_item.january) )/1; \r\n                    }\r\n                   \r\n\r\n                }else{\r\n                    return ( Number(mos_item.january) + Number(mos_item.february) + Number(mos_item.march) + Number(mos_item.april) + Number(mos_item.may) + Number(mos_item.june) + Number(mos_item.july) + Number(mos_item.august) + Number(mos_item.september) + Number(mos_item.october) + Number(mos_item.november) + Number(mos_item.december) ) ; \r\n                }\r\n                \r\n            },        \r\n        },\r\n        computed: {},\r\n    };\r\n    </script>\r\n    ","import mod from \"-!../../../node_modu