      <tr>\r\n                      <th class=\"text-center\" width=\"15%\">\r\n                        <strong>Name</strong>\r\n                      </th>\r\n                      <th class=\"text-center\" width=\"15%\">\r\n                        <strong>Weightage</strong>\r\n                      </th>\r\n                    </tr>\r\n                    <tr>\r\n                      <th class=\"text-center\">\r\n                        {{ item.krajoin ? item.krajoin.kra_name : \"\" }}\r\n                      </th>\r\n                      <th class=\"text-center\">\r\n                        {{ item.krajoin ? item.krajoin.kra_weight : \"\" }}\r\n                      </th>\r\n                    </tr>\r\n                    <tr>\r\n                      <th colspan=\"2\" class=\"text-center\" width=\"15%\">\r\n                        <strong>KPI</strong>\r\n                      </th>\r\n                    </tr>\r\n                    <tr>\r\n                      <th class=\"text-center\">{{ item.kpi_name }}</th>\r\n                      <th class=\"text-center\">{{ item.kpi_weight }}</th>\r\n                    </tr>\r\n                    <tr>\r\n                      <th colspan=\"2\" class=\"text-center\" width=\"15%\">\r\n                        <strong>KPI</strong>\r\n                      </th>\r\n                    </tr>\r\n                    <tr>\r\n                      <th class=\"text-center\">{{ item.kpi_name }}</th>\r\n                      <th class=\"text-center\">{{ item.kpi_weight }}</th>\r\n                    </tr>\r\n                    <tr>\r\n                      <th colspan=\"2\" class=\"text-center\" width=\"15%\">\r\n                        <strong>MOS</strong>\r\n                      </th>\r\n                    </tr>\r\n                    <tr>\r\n                      <th class=\"text-center\">\r\n                        <input\r\n                          class=\"form-control text-center\"\r\n                          placeholder=\"MOS Name\"\r\n                          v-model=\"addForm.mos_name\"\r\n                        />\r\n                      </th>\r\n                      <th class=\"text-center\">\r\n                        <button @click=\"addMOS()\" class=\"btn btn-success\">\r\n                          Save\r\n                        </button>\r\n                      </th>\r\n                    </tr>\r\n                  </tbody>\r\n                </table>\r\n              </div>\r\n            </div>\r\n          </modal>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n</template>\r\n <script>\r\nimport axios from \"../../axios_instance\";\r\nimport { Form } from \"vform\";\r\nexport default {\r\n  props: {},\r\n  components: {\r\n    // VueRecaptcha, facebookLogin\r\n  },\r\n  data() {\r\n    return {\r\n      kpi_id: this.$route.params.id,\r\n      quarter: this.$route.query.quarter,\r\n      month: this.$route.query.month,\r\n      dept_id: this.$route.query.dept_id,\r\n      kra_id: this.$route.query.kra_id,\r\n      base_url: window.base_url,\r\n      api_url: window.api_url,\r\n      token: this.$localStorage.get(\"d_token\"),\r\n      user_data: JSON.parse(this.$localStorage.get(\"user\")),\r\n      item: [],\r\n      mos_item: [],\r\n      feedback_singel: {},\r\n      feedback: {},\r\n      status: \"\",\r\n      month_off: [],\r\n      updateForm: new Form({\r\n        arrayData: {\r\n          mosjoin: [],\r\n        },\r\n        feedback: {},\r\n        year_get: this.$localStorage.get(\"year\")\r\n        ? this.$localStorage.get(\"year\")\r\n        : new Date().getFullYear(),        \r\n      }),\r\n      addForm: new Form({\r\n        mos_name: \"\",\r\n        weightage: 0,\r\n      }),\r\n      updateFeed: new Form({}),\r\n\r\n      year: this.$localStorage.get(\"year\")\r\n        ? this.$localStorage.get(\"year\")\r\n        : new Date().getFullYear(),\r\n    };\r\n  },\r\n  created() {\r\n    this.role_id = this.user_data.role_id;\r\n    if (this.role_id == 5 || this.role_id == 6 || this.role_id == 7 || this.role_id == 10) {\r\n      this.getDepartment().then(({ data }) => {\r\n        if (data.success) {\r\n          this.month_off = data.data.setting;\r\n          console.log(this.month_off);\r\n        }\r\n      });\r\n    }\r\n    this.getItems();\r\n  },\r\n  methods: {\r\n    back() {\r\n      this.$router.go(-1);\r\n    },\r\n    hide_pop_feedback() {\r\n      this.$modal.hide(\"feedback\");\r\n    },\r\n    show_pop_feedback(feed) {\r\n      this.feedback_singel = feed;\r\n      this.$modal.show(\"feedback\");\r\n    },\r\n    hide_pop() {\r\n      this.$modal.hide(\"popup-singel\");\r\n    },\r\n    show_pop() {\r\n      this.$modal.show(\"popup-singel\");\r\n    },\r\n    target(mos_item) {\r\n      return (\r\n        Number(mos_item.january) +\r\n        Number(mos_item.february) +\r\n        Number(mos_item.march) +\r\n        Number(mos_item.april) +\r\n        Number(mos_item.may) +\r\n        Number(mos_item.june) +\r\n        Number(mos_item.july) +\r\n        Number(mos_item.august) +\r\n        Number(mos_item.september) +\r\n        Number(mos_item.october) +\r\n        Number(mos_item.november) +\r\n        Number(mos_item.december)\r\n      );\r\n    },\r\n    onlyNumber($event) {\r\n      //console.log($event.keyCode); //keyCodes value\r\n      let keyCode = $event.keyCode ? $event.keyCode : $event.which;\r\n      if ((keyCode < 48 || keyCode > 57) && keyCode !== 46) {\r\n        // 46 is dot\r\n        $event.preventDefault();\r\n      }\r\n    },\r\n    checkConditionKra(length, kpi_index, mos_index) {\r\n      if (kpi_index == 0 && mos_index == 0) {\r\n        return true;\r\n      } else {\r\n        return false;\r\n      }\r\n    },\r\n    checkConditionKpi(length, mos_index) {\r\n      if (mos_index == 0) {\r\n        return true;\r\n      } else {\r\n        return false;\r\n      }\r\n    },\r\n    async delete_feedback(item) {\r\n      let loader = this.$loading.show();\r\n      try {\r\n        await axios\r\n          .delete(this.api_url + \"mos_feadbacks/\" + item.id, {\r\n            headers: {\r\n              \"Content-Type\": \"application/json\",\r\n              Authorization: this.token ? `Bearer ${this.token}` : \"\",\r\n            },\r\n          })\r\n          .then(({ res }) => {\r\n            this.getItems();\r\n            if (res.data.success) {\r\n              this.$toasted.show(res.data.message, {\r\n                theme: \"bubble\",\r\n                duration: 5000,\r\n                position: \"bottom-right\",\r\n              });\r\n            }\r\n            loader.hide();\r\n          });\r\n      } catch (error) {\r\n        loader.hide();\r\n      }\r\n    },\r\n    feedbackUpdate() {\r\n      try {\r\n        let loader = this.$loading.show();\r\n        //`mos_id`, `user_id`, `dept_id`, `date`, `msg`, `month`, `fmonth`, `status`\r\n        this.updateFeed.msg = this.feedback_singel.msg;\r\n        this.updateFeed.mos_id = this.feedback_singel.mos_id;\r\n        this.updateFeed\r\n          .put(this.api_url + \"mos_feadbacks/\" + this.feedback_singel.id, {\r\n            headers: {\r\n              \"Content-Type\": \"application/json\",\r\n              Authorization: this.token ? `Bearer ${this.token}` : \"\",\r\n            },\r\n          })\r\n          .then(\r\n            (res) => {\r\n              console.log(res);\r\n              this.hide_pop_feedback();\r\n              if (res.data.success) {\r\n                this.$toasted.show(res.data.message, {\r\n                  theme: \"bubble\",\r\n                  duration: 5000,\r\n                  position: \"bottom-right\",\r\n                });\r\n              }\r\n              loader.hide();\r\n              //this.$router.push('/daily_work');\r\n            },\r\n            (error) => {\r\n              console.log(error);\r\n              loader.hide();\r\n            }\r\n          );\r\n      } catch (error) {\r\n        // loader.hide();\r\n        console.log(error);\r\n      }\r\n    },\r\n    updateMOS() {\r\n\r\n      // try {\r\n      let loader = this.$loading.show();\r\n      this.updateForm.arrayData.mosjoin[0] = this.mos_item;\r\n      this.updateForm.feedback = this.feedback;\r\n      this.updateForm\r\n        .post(this.api_url + \"mos_update\", {\r\n          headers: {\r\n            \"Content-Type\": \"application/json\",\r\n            Authorization: this.token ? `Bearer ${this.token}` : \"\",\r\n          },\r\n        })\r\n        .then((res) => {\r\n          console.log(res);\r\n          if (res.data.success) {\r\n            this.$toasted.show(res.data.message, {\r\n              theme: \"bubble\",\r\n              duration: 5000,\r\n              position: \"bottom-right\",\r\n            });\r\n          }\r\n          loader.hide();\r\n        });\r\n      // } catch (error) {\r\n      // console.log(error);\r\n      // }\r\n      console.log(this.item);\r\n    },\r\n    addMOS() {\r\n      try {\r\n        let loader = this.$loading.show();\r\n        this.addForm.kra_id = this.item.krajoin.id;\r\n        this.addForm.kpi_id = this.item.id;\r\n        this.addForm.dept_id = this.item.dept_id;\r\n        this.addForm\r\n          .post(this.api_url + \"m_o_s\", {\r\n            headers: {\r\n              \"Content-Type\": \"application/json\",\r\n              Authorization: this.token ? `Bearer ${this.token}` : \"\",\r\n            },\r\n          })\r\n          .then((res) => {\r\n            console.log(res);\r\n            if (res.data.success) {\r\n              this.hide_pop();\r\n              this.getItems();\r\n              this.$toasted.show(res.data.message, {\r\n                theme: \"bubble\",\r\n                duration: 5000,\r\n                position: \"bottom-right\",\r\n              });\r\n            }\r\n            loader.hide();\r\n          });\r\n      } catch (error) {\r\n        console.log(error);\r\n      }\r\n      console.log(this.item);\r\n    },\r\n    async getItems() {\r\n      let loader = this.$loading.show();\r\n      try {\r\n        await axios\r\n          .get(this.api_url + \"m_o_s/\" + this.kpi_id + \"?year=\" + this.year, {\r\n            headers: {\r\n              \"Content-Type\": \"application/json\",\r\n              Authorization: this.token ? `Bearer ${this.token}` : \"\",\r\n            },\r\n          })\r\n          .then(({ data }) => {\r\n            if (data.success) {\r\n              this.mos_item = data.data;\r\n              console.log(this.item);\r\n            }\r\n            loader.hide();\r\n          });\r\n      } catch (error) {\r\n        loader.hide();\r\n      }\r\n    },\r\n  },\r\n  computed: {},\r\n};\r\n</script>\r\n \r\n ","import mod from \"-!../../../node_modules/cache-loader/dist/cjs.js??ref--12-0!../../../node_modules/thread-loader/dist/cjs.js!../../../node_modules/babel-loader/lib/index.js!../../../node_modules/cache-loader/dist/cjs.js??ref--0-0!../../../node_modules/vue-loader/lib/index.js??vue-loader-options!./achievement.vue?vue&type=script&lang=js&\"; export default mod; export * from \"-!../../../node_modules/cache-loader/dist/cjs.js??ref--12-0!../../../node_modules/thread-loader/dist/cjs.js!../../../node_modules/babel-loader/lib/index.js!../../../node_modules/cache-loader/dist/cjs.js??ref--0-0!../../../node_modules/vue-loader/lib/index.js??vue-loader-options!./achievement.vue?vue&type=script&lang=js&\"","import { render, staticRenderFns } from \"./achievement.vue?vue&type=template&id=b36c738e&\"\nimport script from \"./achievement.vue?vue&type=script&lang=js&\"\nexport * from \"./achievement.vue?vue&type=script&lang=js&\"\n\n\n/* normalize component */\nimport normalizer from \"!../../../node_modules/vue-loader/lib/runtime/componentNormalizer.js\"\nvar component = normalizer(\n  script,\n  render,\n  staticRenderFns,\n  false,\n  null,\n  null,\n  null\n  \n)\n\nexport default component.exports","var render