                  >\r\n                      <option value=\"\">Select month</option>\r\n                      <option value=\"1\">Jan</option>\r\n                      <option value=\"2\">Feb</option>\r\n                      <option value=\"3\">Mar</option>\r\n                      <option value=\"4\">Apr</option>\r\n                      <option value=\"5\">May</option>\r\n                      <option value=\"6\">Jun</option>\r\n                      <option value=\"7\">Jul</option>\r\n                      <option value=\"8\">Aug</option>\r\n                      <option value=\"9\">Sep</option>\r\n                      <option value=\"10\">Oct</option>\r\n                      <option value=\"11\">Nov</option>\r\n                      <option value=\"12\">Dec</option>\r\n                    </select>\r\n                  </fieldset>\r\n                </div>\r\n              </div>\r\n            </div>\r\n\r\n            <div class=\"row\">\r\n              <div class=\"col-12\">\r\n                <div class=\"card\">\r\n                  <div class=\"card-content\">\r\n                    <div class=\"card-body card-dashboard\">\r\n                      <div class=\"card\">\r\n                        <div class=\"card-content\">\r\n                          <div class=\"card-body card-dashboard\">\r\n                            <div class=\"table-responsive\">\r\n                              <table class=\"table table-bordered table-sm\">\r\n                                <thead class=\"thead-dark\">\r\n                                  <tr>\r\n                                    <th class=\"text-center\">SL</th>\r\n                                    <th class=\"text-center\">Department name</th>\r\n                                    <th class=\"text-center\">No. of employee</th>\r\n                                    <th class=\"text-center\">Update</th>\r\n                                    <th class=\"text-center\">Due</th>\r\n                                  </tr>\r\n                                </thead>\r\n                                <tbody class=\"text-center\">\r\n                                  <tr\r\n                                    v-for=\"(row, index) in items\"\r\n                                    :key=\"row.id\"\r\n                                  >\r\n                                    <td>{{ (index += 1) }}</td>\r\n                                    <td>{{ row.name }}</td>\r\n                                    <td>{{ row.users }}</td>\r\n                                    <td>{{ row.kra_updated }}</td>\r\n                                    <td>{{ row.kra_due }}</td>\r\n                                  </tr>\r\n                                  <tr>\r\n                                    <th class=\"text-center\" colspan=\"2\">Total</th>\r\n                                    <th class=\"text-center\">{{total_emp}}</th>\r\n                                    <th class=\"text-center\">{{updated_emp}}</th>\r\n                                    <th class=\"text-center\">{{due_emp}}</th>\r\n                                  </tr>\r\n                                </tbody>\r\n                              </table>\r\n                            </div>\r\n                          </div>\r\n                        </div>\r\n                      </div>\r\n                    </div>\r\n                  </div>\r\n                </div>\r\n              </div>\r\n            </div>\r\n          </section>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n</template>\r\n\r\n<script>\r\nimport axios from \"../../axios_instance\";\r\nimport { Form } from \"vform\";\r\n\r\nexport default {\r\n  props: {},\r\n  components: {\r\n    // VueRecaptcha, facebookLogin\r\n  },\r\n  data() {\r\n    return {\r\n      base_url: window.base_url,\r\n      api_url: window.api_url,\r\n      DepartmentsItems: [],\r\n      user_data: JSON.parse(this.$localStorage.get(\"user\")),\r\n      tok