zation: this.token ? `Bearer ${this.token}` : \"\"\r\n                    },\r\n                }).then((res) => {\r\n                    if(res.data.success){\r\n                            this.$toasted.show(res.data.message, {\r\n                            theme: \"bubble\",\r\n                            duration: 5000,\r\n                            position: \"bottom-right\",\r\n                        });\r\n                    } \r\n                    loader.hide(); \r\n                    this.items();\r\n                },(error)=>{\r\n                    console.log(error);\r\n                    loader.hide(); \r\n                })\r\n            },\r\n        },\r\n        computed: {\r\n            \r\n        },\r\n    };\r\n</script>","import mod from \"-!../../../node_modules/cache-loader/dist/cjs.js??ref--12-0!../../../node_modules/thread-loader/dist/cjs.js!../../../node_modules/babel-loader/lib/index.js!../../../node_modules/cache-loader/dist/cjs.js??ref--0-0!../../../node_modules/vue-loader/lib/index.js??vue-loader-options!./mos_assign.vue?vue&type=script&lang=js&\"; export default mod; export * from \"-!../../../node_modules/cache-loader/dist/cjs.js??ref--12-0!../../../node_modules/thread-loader/dist/cjs.js!../../../node_modules/babel-loader/lib/index.js!../../../node_modules/cache-loader/dist/cjs.js??ref--0-0!../../../node_modules/vue-loader/lib/index.js??vue-loader-options!./mos_assign.vue?vue&type=script&lang=js&\"","import { render, staticRenderFns } from \"./mos_assign.vue?vue&type=template&id=1d5b60b8&\"\nimport script from \"./mos_assign.vue?vue&type=script&lang=js&\"\nexport * from \"./mos_assign.vue?vue&type=script&lang=js&\"\n\n\n/* normalize component */\nimport normalizer from \"!../../../node_modules/vue-loader/lib/runtime/componentNormalizer.js\"\nvar component = normalizer(\n  script,\n  render,\n  staticRenderFns,\n  false,\n  null,\n  null,\n  null\n  \n)\n\nexport default component.exports","var render = function () {var _vm