{ Number(item.consumtion  ?    item.previous_year_average  - (item.actual_wastage / item.consumtion) * 100   : 0).toFixed(2) }}%  </td>\r\n                                                                    <!-- previous  -->\r\n                                                                    <td class=\"previous text-right\">{{ formatPrice(item.actual_wastage_previous) }} </td>\r\n                                                                    <td class=\"previous text-right\">{{ formatPrice(item.consumtion_previous) }}</td>\r\n                                                                    <td class=\"previous text-right\">{{ Number(item.consumtion_previous  ? (item.actual_wastage_previous / item.consumtion_previous) * 100: 0).toFixed(2) }} %</td>\r\n                                                                    <td class=\" text-right\">{{ Number(item.current_year_average).toFixed(2) }}%</td>\r\n                                                                </tr>\r\n                                                                <tr  v-if=\"wastage.length > 0 && watt5_show == 1 \" >\r\n                                                                    <td colspan=\"11\" class=\"text-right\">\r\n                                                                        <a class=\"btn btn-primary add-btn\"  style=\"color: #efefef;\"  @click=\"show_pop('wastage')\" > <i class=\"bx bx-add-alt\"></i>Feedback</a>   \r\n                                                                    </td>\r\n                                                                </tr>\r\n                                                                </tbody>\r\n                                                                 \r\n                                                            </table>\r\n                                                        </td>\r\n                                                    </tr>\r\n                                                    