r, staticRenderFns }","<template>\r\n<div>\r\n    <div class=\"app-content content\">\r\n        <div class=\"content-wrapper\">\r\n            <div class=\"content-header row\">\r\n                <div class=\"content-header-left col-12 mb-1 mt-0\">\r\n                    <div class=\"row breadcrumbs-top\">\r\n                        <div class=\"col-sm-8\">\r\n                            <div class=\"breadcrumb-wrapper col-9\">\r\n                                <ol class=\"breadcrumb p-0 mb-0\">\r\n                                    <li class=\"breadcrumb-item\">\r\n                                        <router-link :to=\"{ path: '/' }\"><i class=\"bx bx-home-alt\"></i></router-link>\r\n                                    </li>\r\n                                    <li class=\"breadcrumb-item active\"> Products\r\n                                    </li>\r\n                                </ol>\r\n                            </div>\r\n                        </div>\r\n<!--                        <div class=\" col-sm-2\">\r\n                            <a class=\"btn btn-primary add-btn\" @click=\"show_pop()\" > <i class=\"bx bx-add-alt\"></i>Product Upload</a> \r\n                        </div>\r\n                        <div class=\" col-sm-2\">\r\n                            <router-link class=\"btn btn-primary add-btn\" :to=\"{ path: '/new_product' }\"> <i class=\"bx bx-add-alt\"></i> Add Product</router-link>\r\n                        </div>-->\r\n                    </div>\r\n                </div>\r\n            </div>\r\n            <div class=\"content-body\">  \r\n                <section id=\"basic-datatable\">\r\n                    <div  class=\"users-list-filter px-1\"> \r\n                        <div class=\"row border rounded py-2 mb-2\">\r\n                            <div class=\"col-12 col-sm-6 col-lg-2\">\r\n                                <label for=\"users-list-verified\">Factorys</label>\r\n                                <fieldset class=\"form-group\">\r\n                                <select class=\"form-control\"  v-on:change=\"summaryList()\"   v-model=\"filterForm.factory_id\"  id=\"users-list-verified\" >\r\n                                    <option value=\"\">Select One</option>\r\n                                    <option v-for=\"row in itemsFactorys\" :key=\"row.id\" :value=\"row.id\" >\r\n                                    {{ row.dis_name }}\r\n                                    </option>\r\n                                </select>\r\n                                \r\n                                </fieldset>\r\n                            </div>\r\n                            <div   class=\"col-12 col-sm-6 col-lg-2\">\r\n                                <label for=\"users-list-verified\">Product group</label>\r\n                                <fieldset class=\"form-group\">\r\n                                <select required=\"\" class=\"form-control\"   v-on:change=\"getItems()\"  v-model=\"filterForm.summary_group_id\">\r\n                                    <option value=\"\">Select Product group</option>\r\n                                    <option  v-for=\"row in itemsSummaryGroup\" :key=\"row.id\" :value=\"row.id\" >{{ row.description }}</option>\r\n                                        \r\n                                </select> \r\n                                </fieldset>\r\n                            </div>\r\n                            <div   class=\"col-12 col-sm-6 col-lg-2\">\r\n                                <label for=\"users-list-verified\">Material Code</label>\r\n                                <fieldset class=\"form-group\">\r\n                                    <input type=\"text\" name=\"material_code\" v-model=\"filterForm.material_code\" :class=\"{  'is-invalid': filterForm.errors.has('material_code'),  }\" class=\"form-control\" data-validation-required-message=\"This field is required\" placeholder=\"Material Code\">\r\n                                </fieldset>\r\n                            </div>\r\n                            <!-- <div   class=\"col-12 col-sm-6 col-lg-2\">\r\n                            <label class=\"control-label\">From</label>\r\n                                <fieldset class=\"form-group\"> \r\n                                <datepicker v-model=\"filterForm.start_date\" name=\"start_date\" class=\"form-control\"  ></datepicker> \r\n                                </fieldset>\r\n                            </div> \r\n                            <div   class=\"col-12 col-sm-6 col-lg-2\">\r\n                                <label for=\"users-list-verified\">To </label>\r\n                                <fieldset class=\"form-group\">\r\n                                <datepicker v-model=\"filterForm.end_date\" name=\"end_date\" class=\"form-control\"  ></datepicker> \r\n                                </fieldset>\r\n                            </div>\r\n                            <div   class=\"col-12 col-sm-6 col-lg-2\">\r\n                            <label class=\"control-label\">From (Previous)</label>\r\n                            <fieldset class=\"form-group\">\r\n                                <datepicker v-model=\"filterForm.start_date_previous\" name=\"start_date_previous\" class=\"form-control\"  ></datepicker> \r\n                            </fieldset> \r\n                            </div>\r\n                            <div   class=\"col-12 col-sm-6 col-lg-2\">\r\n                            <label class=\"control-label\">To (Previous)</label>\r\n                            <fieldset class=\"form-group\">\r\n                                <datepicker v-model=\"filterForm.end_date_previous\" name=\"end_date_previous\" class=\"form-control\"  ></datepicker> \r\n                            </fieldset> \r\n                            </div> -->\r\n                            <div   class=\"col-12 col-sm-6 col-lg-2\">\r\n                                <label for=\"users-list-verified\">Limit</label>\r\n                                <fieldset class=\"form-group\">\r\n                                    <select  v-on:change=\"getItems()\"   class=\"form-control\"  v-model=\"filterForm.limit\">  \r\n                                        <option value=\"100\">100</option>\r\n                                        <option value=\"500\">500</option>\r\n                                        <option value=\"1000\">1000</option>\r\n                                        <option value=\"2000\">2000</option> \r\n                                        <option value=\"5000\">5000</option> \r\n                                        <option value=\"2000000\">All</option> \r\n                                    </select> \r\n                                </fieldset>\r\n                            </div>\r\n                            <div   class=\"col-12 col-sm-6 col-lg-1_5\"> \r\n                                <option value=\"\"></option>\r\n                            <fieldset class=\"form-group\">\r\n                                <button type=\"submit\" @click=\"getItems()\" class=\"btn btn-primary mb-2\">Submit</button>\r\n                            </fieldset> \r\n                            </div>\r\n                        </div> \r\n                     </div>\r\n\r\n\r\n                    <div class=\"row\"> \r\n                        <div class=\"col-12\">\r\n                            <div class=\"card\">\r\n                                <div class=\"card-content\">\r\n                                    <div class=\"card-body card-dashboard\">\r\n\r\n                                      <div class=\"btn-group mb-1\" role=\"group\" aria-label=\"Basic example\">\r\n\r\n                                        <!-- PRODUCT UPLOAD -->\r\n                                        <!-- <button type=\"button\" class=\"btn btn-primary add-btn btn-lg d-flex align-items-center\">\r\n                                          <a class=\"text-white\" @click=\"show_pop()\" > <i class=\"\"></i>Product Upload</a>\r\n                                        </button> -->\r\n\r\n                                        <!-- ADD PRODUCT -->\r\n                                        <!-- <button type=\"button\" class=\"btn btn-primary add-btn btn-lg d-flex align-items-center\">\r\n                                          <router-link class=\"text-white\" :to=\"{ path: '/new_product' }\"> <i class=\"bx bx-add-alt\"></i> Add Product</router-link>\r\n                                        </button> -->\r\n                                      </div>\r\n\r\n                                        <div class=\"table-responsive\">\r\n                                            <table class=\"table table-striped\"> \r\n                                                    <thead> \r\n                                                       \r\n                                                      <tr> \r\n                                                        <th>SL</th> \r\n                                                        <th>Plant</th>  \r\n                                                        <th>Material Group</th> \r\n                                                        <th>Material Code</th>\r\n                                                        <th>Description</th>\r\n                                                        <th>Base unit of Measure</th>  \r\n                                                        <th>Action</th>  \r\n                                                      </tr>\r\n                                                    </thead>\r\n                                                    <tbody>\r\n                                                      <tr  v-for=\"(item , index) in items\" :key=\"item.id\" > \r\n                                                        <td>{{ index + 1  }}</td>\r\n                                                        <td>{{ item.plant }}</td>\r\n                                                        <td>{{ item.product_group }}</td>  \r\n                                                        <td>{{ item.material_code }} </td>\r\n                                                        <td>{{ item.description }} </td>\r\n                                                        <td>{{ item.base_unit_of_measure }} </td>  \r\n                                                        <td>\r\n                                                            <div class=\"dropup\">\r\n                                                                <span class=\"bx bx-dots-vertical-rounded font-medium-3 dropdown-toggle nav-hide-arrow cursor-pointer\" data-toggle=\"dropdown\" aria-haspopup=\"true\" aria-expanded=\"false\" role=\"menu\">\r\n                                                                </span>\r\n                                                                <div class=\"dropdown-menu dropdown-menu-right\"> \r\n                                                                    <router-link target=\"_blank\" :to=\"{ path: '/product_edit/'+item.id }\" class=\"dropdown-item\">\r\n                                                                        <i class=\"bx bx-edit-alt mr-1\">\r\n                                                                        </i>\r\n                                                                        Details\r\n                                                                    </router-link> \r\n                                                                </div>\r\n                                                            </div>\r\n                                                        </td>  \r\n                                                      </tr> \r\n                                                    </tbody>\r\n                                                  </table>\r\n                                        </div>\r\n                                    </div>\r\n                                </div>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                </section>\r\n                <modal name=\"popup-singel\">\r\n                    <i @click=\"hide_pop()\" class=\"bx bx-x-circle  x-circle\"></i>\r\n                    <div class=\"card\">\r\n                       <div class=\"row\">\r\n                        <div class=\"col-sm-6\"> \r\n                            <a class=\"btn-block glow users-list-clear mb-0 download_template\"  >Material Data Upload</a>\r\n                            <br>\r\n                        </div>\r\n                          <table class=\"table table-bordered table-striped table-sm\">\r\n                             <tbody> \r\n                                \r\n                                <tr>\r\n                                   <th class=\"text-center\">\r\n                                    <input type=\"file\" accept=\".xlsx\" class=\"form-control\" ref=\"file\" @change=\"handleFileObject()\" /> \r\n                                   </th>\r\n                                   <th class=\"text-center\">\r\n                                      <button @click=\"csvUpload()\" class=\"btn btn-success\">Save</button>\r\n                                   </th>\r\n                                </tr>\r\n                             </tbody>\r\n                          </table>\r\n                          <div class=\"col-sm-12\"> \r\n                            <router-link to=\"/demo/New_Material_Upload.xlsx\"> New Material Upload Template</router-link>\r\n                            \r\n                            <br>\r\n                        </div>\r\n                       </div>\r\n                   </div>\r\n                 </modal>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</div>\r\n</template>\r\n\r\n<script>\r\nimport axios from \"../../axios_instance\";\r\nimport { Form } from \"vform\"; \r\nexport default {\r\n    props: {},\r\n    components: {\r\n        // VueRecaptcha, facebookLogin\r\n    },\r\n    data() {\r\n        return {\r\n            base_url: window.base_url,\r\n            api_url: window.api_url,\r\n            token: this.$localStorage.get(\"d_token\"),\r\n            items: [],\r\n            csv: null,\r\n            csvName: null,   \r\n            filterForm: new Form({  \r\n                factory_id: \"\",    \r\n                summary_group_id : \"\",\r\n                limit : 100 ,\r\n            }),\r\n            status: '',\r\n            csvform: { \r\n            },\r\n            itemsFactorys: [],   \r\n            itemsSummaryGroup: [], \r\n        };\r\n    },\r\n    created() { \r\n        this.getFactorys(); \r\n        this.getItems(); \r\n    },\r\n    methods: { \r\n         hide_pop() {\r\n            this.$modal.hide(\"popup-singel\");\r\n        },\r\n        show_pop() { \r\n            this.$modal.show(\"popup-singel\"); \r\n        },\r\n        handleFileObject() {\r\n            this.csv = this.$refs.file.files[0];\r\n            console.log(this.csv);\r\n            this.csvName = this.csv.name;\r\n        },\r\n        csvFile() {\r\n            let file = event.target.files[0];\r\n            let reader = new FileReader();\r\n            reader.readAsDataURL(file);\r\n            reader.onload = (event) => {\r\n                this.csvform.csv = event.target.result;\r\n            };\r\n        },\r\n        csvUpload() {\r\n            \r\n                let formData = new FormData();\r\n              \r\n                formData.append(\"csvFile\", this.csv); \r\n                let loader = this.$loading.show();\r\n                axios\r\n                    .post(this.api_url + \"product-file-upload\", formData, {\r\n                        headers: {\r\n                            \"Content-Type\": \"multipart/form-data\",\r\n                            Authorization: this.token ? `Bearer ${this.token}` : \"\",\r\n                        },\r\n                    })\r\n                    .then((res) => {\r\n                            console.log(res.data.message);\r\n                            loader.hide();\r\n                            this.$modal.hide('file-upload');\r\n                            this.$swal({\r\n                                title: res.data.message , \r\n                                icon: \"warning\",\r\n                            });\r\n                            this.getItems();\r\n                        },\r\n                        (err) => {\r\n                            loader.hide();\r\n                            console.log(err);\r\n                        }\r\n                    );\r\n             \r\n        },\r\n        async getItems() {\r\n            if(this.filterForm.summary_group_id || this.filterForm.material_code ){ \r\n                let where = '?1=1';  \r\n                if(this.filterForm.summary_group_id){\r\n                    where +='&summary_group_id='+this.filterForm.summary_group_id ;\r\n                }\r\n                if(this.filterForm.factory_id){\r\n                    where +='&factory_id='+this.filterForm.factory_id ;\r\n                }\r\n                if(this.filterForm.material_code){\r\n                    where +='&material_code='+this.filterForm.material_code ;\r\n                }\r\n                let loader = this.$loading.show();\r\n                try {\r\n                    await axios\r\n                        .get(this.api_url + \"products\" + where, {\r\n                            headers: {\r\n                                \"Content-Type\": \"application/json\",\r\n                                Authorization: this.token ? `Bearer ${this.token}` : \"\"\r\n                            },\r\n                        })\r\n                        .then(({\r\n                            data\r\n       