ect class=\"form-control\"  v-on:change=\"getItems()\"  v-model=\"filterForm.cost_center_id\"  id=\"users-list-verified\" >\r\n                                    <option value=\"\">Select One</option>\r\n                                    <option v-for=\"row in cost_centers\" :key=\"row.id\" :value=\"row.id\" >\r\n                                    {{ row.name }}\r\n                                    </option>\r\n                                </select>\r\n                                \r\n                                </fieldset>\r\n                            </div> \r\n                            \r\n                        </div> \r\n                     </div>\r\n                    <div class=\"row\"> \r\n                        <div class=\"col-12\">\r\n                            <div class=\"card\">\r\n                                <div class=\"card-content\">\r\n                                    <div class=\"card-body card-dashboard\">\r\n\r\n                                      <div class=\"btn-group mb-1\" role=\"group\" aria-label=\"Basic example\">\r\n\r\n                                        <!-- DATA UPLOAD -->\r\n                                        <button type=\"button\" class=\"btn btn-primary add-btn btn-lg d-flex align-items-center\">\r\n                                          <a class=\"text-white\" @click=\"show_pop()\" > <i class=\"bx bx-add-alt\"></i>Data Upload </a>\r\n                                        </button>\r\n                                      </div>\r\n\r\n                                        <div class=\"table-responsive\">\r\n                                            <table class=\"table table-striped\"> \r\n                                                    <thead>  \r\n                                                      <tr>\r\n                                                        <th>Sl</th>\r\n                                                        <th>Cost Center</th>\r\n               